args.CodeContent:
:root {
  --bg-app: #0b0f19;
  --bg-panel: #111827;
  --bg-card: #1e293b;
  --bg-card-hover: #263349;
  --bg-input: #0f172a;
  --border-color: #1f2937;
  --border-highlight: #334155;

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;

  --accent-primary: #6366f1;
  --accent-primary-glow: rgba(99, 102, 241, 0.25);
  --accent-secondary: #06b6d4;
  --accent-success: #10b981;
  --accent-success-bg: rgba(16, 185, 129, 0.14);
  --accent-warning: #f59e0b;
  --accent-warning-bg: rgba(245, 158, 11, 0.15);
  --accent-danger: #ef4444;
  --accent-danger-bg: rgba(239, 68, 68, 0.15);
  --accent-purple: #a855f7;

  --line-current-bg: rgba(99, 102, 241, 0.22);
  --line-current-border: #6366f1;
  --line-next-bg: rgba(245, 158, 11, 0.12);
  --line-next-border: #f59e0b;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Consolas, monospace;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-app);
  color: var(--text-primary);
  font-family: var(--font-sans);
  height: 100vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

/* Header Navigation */
.app-header {
  height: 60px;
  background: rgba(17, 24, 39, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  flex-shrink: 0;
  z-index: 20;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-logo {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--accent-primary), var(--accent-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 18px;
  color: white;
  box-shadow: 0 0 18px var(--accent-primary-glow);
}

.brand-title {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.badge-ai {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(99, 102, 241, 0.18);
  color: #818cf8;
  border: 1px solid rgba(99, 102, 241, 0.35);
}

.brand-subtitle {
  font-size: 12px;
  color: var(--text-secondary);
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

.control-group {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-input);
  padding: 4px 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-highlight);
}

.control-label {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 500;
}

select.preset-select {
  background: transparent;
  color: var(--text-primary);
  border: none;
  font-size: 13px;
  font-family: var(--font-sans);
  font-weight: 500;
  outline: none;
  cursor: pointer;
  padding-right: 6px;
}

select.preset-select option {
  background: var(--bg-panel);
  color: var(--text-primary);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 600;
  font-family: var(--font-sans);
  cursor: pointer;
  border: 1px solid var(--border-highlight);
  background: var(--bg-card);
  color: var(--text-primary);
  transition: all 0.16s ease;
}

.btn:hover:not(:disabled) {
  background: var(--bg-card-hover);
  border-color: #475569;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent-primary), #4f46e5);
  border-color: #6366f1;
  color: white;
  box-shadow: 0 2px 12px var(--accent-primary-glow);
}

.btn-primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #4f46e5, #4338ca);
  border-color: #818cf8;
}

.btn-quiz {
  background: rgba(168, 85, 247, 0.15);
  border-color: rgba(168, 85, 247, 0.4);
  color: #d8b4fe;
}

.btn-quiz.active {
  background: var(--accent-purple);
  color: white;
}

/* Playback Transport Bar */
.transport-bar {
  height: 54px;
  background: var(--bg-panel);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  gap: 20px;
  flex-shrink: 0;
}

.transport-buttons {
  display: flex;
  align-items: center;
  gap: 6px;
}

.btn-icon {
  padding: 6px 10px;
  min-width: 36px;
  font-size: 13px;
}

.btn-play {
  min-width: 92px;
  background: var(--accent-success);
  border-color: #059669;
  color: #052e16;
  font-weight: 700;
}

.btn-play:hover:not(:disabled) {
  background: #34d399;
}

.btn-play.playing {
  background: var(--accent-warning);
  border-color: #d97706;
  color: #451a03;
}

.scrubber-container {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 14px;
  max-width: 680px;
}

.step-counter {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--bg-input);
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-highlight);
  white-space: nowrap;
}

.scrubber-track-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

input[type="range"].timeline-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 999px;
  background: var(--bg-card);
  outline: none;
  cursor: pointer;
}

input[type="range"].timeline-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-primary);
  border: 2px solid white;
  box-shadow: 0 0 8px var(--accent-primary);
  cursor: pointer;
  transition: transform 0.12s ease;
}

input[type="range"].timeline-slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.speed-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.speed-pill {
  padding: 4px 8px;
  font-size: 11px;
  font-family: var(--font-mono);
  border-radius: var(--radius-sm);
  background: var(--bg-input);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  cursor: pointer;
}

.speed-pill.active {
  background: rgba(99, 102, 241, 0.2);
  color: #a5b4fc;
  border-color: var(--accent-primary);
}

/* Main 3-Column Workspace */
.workspace-grid {
  flex: 1;
  display: grid;
  grid-template-columns: 1.15fr 1.15fr 1fr;
  gap: 1px;
  background: var(--border-color);
  overflow: hidden;
}

.panel {
  background: var(--bg-panel);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.panel-header {
  height: 42px;
  padding: 0 14px;
  background: rgba(15, 23, 42, 0.7);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.panel-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}

.dot-blue { background: var(--accent-primary); }
.dot-cyan { background: var(--accent-secondary); }
.dot-green { background: var(--accent-success); }
.dot-purple { background: var(--accent-purple); }
.dot-amber { background: var(--accent-warning); }

.panel-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tab-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.tab-btn.active {
  background: var(--bg-card);
  color: var(--text-primary);
}

/* LEFT COLUMN: Code Editor + Trace View + Console */
.code-container {
  flex: 1;
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.code-mode-banner {
  background: rgba(99, 102, 241, 0.1);
  border-bottom: 1px solid rgba(99, 102, 241, 0.25);
  padding: 6px 14px;
  font-size: 12px;
  color: #cbd5e1;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.legend-pills {
  display: flex;
  gap: 12px;
  font-size: 11px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
}

.legend-box {
  width: 10px;
  height: 10px;
  border-radius: 3px;
}

.legend-current {
  background: var(--line-current-bg);
  border: 1.5px solid var(--line-current-border);
}

.legend-next {
  background: var(--line-next-bg);
  border: 1.5px solid var(--line-next-border);
}

.code-trace-view {
  flex: 1;
  overflow-y: auto;
  padding: 10px 0;
  font-family: var(--font-mono);
  font-size: 13.5px;
  line-height: 1.65;
  background: var(--bg-input);
}

.code-line {
  display: flex;
  align-items: center;
  padding: 2px 14px 2px 0;
  border-left: 3px solid transparent;
  position: relative;
  transition: background 0.15s ease;
}

.code-line:hover {
  background: rgba(255, 255, 255, 0.02);
}

.code-line.is-current {
  background: var(--line-current-bg);
  border-left-color: var(--line-current-border);
}

.code-line.is-next {
  background: var(--line-next-bg);
  border-left-color: var(--line-next-border);
}

.code-line.is-visited .line-num {
  color: #94a3b8;
}

.line-gutter {
  width: 54px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 12px;
  gap: 4px;
  user-select: none;
  flex-shrink: 0;
}

.line-arrow {
  font-size: 11px;
  width: 16px;
  text-align: center;
}

.line-num {
  color: var(--text-muted);
  font-size: 12px;
}

.line-code {
  white-space: pre;
  color: #e2e8f0;
  flex: 1;
}

.line-inline-values {
  margin-left: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.inline-pill {
  font-size: 11px;
  padding: 1px 7px;
  border-radius: 99px;
  background: rgba(6, 182, 212, 0.16);
  border: 1px solid rgba(6, 182, 212, 0.35);
  color: #67e8f9;
  white-space: nowrap;
}

.inline-pill.branch-true {
  background: var(--accent-success-bg);
  border-color: rgba(16, 185, 129, 0.4);
  color: #6ee7b7;
}

.inline-pill.branch-false {
  background: var(--accent-danger-bg);
  border-color: rgba(239, 68, 68, 0.4);
  color: #fca5a5;
}

.code-editor-textarea {
  flex: 1;
  width: 100%;
  background: var(--bg-input);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 13.5px;
  line-height: 1.65;
  padding: 14px;
  border: none;
  outline: none;
  resize: none;
}

.hidden {
  display: none !important;
}

/* Console Output Panel */
.console-panel {
  height: 160px;
  border-top: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  background: #090d16;
  flex-shrink: 0;
}

.console-body {
  flex: 1;
  padding: 10px 14px;
  font-family: var(--font-mono);
  font-size: 12.5px;
  overflow-y: auto;
  color: #a7f3d0;
}

.console-line {
  padding: 3px 0;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.05);
  display: flex;
  align-items: center;
  gap: 8px;
}

.console-line.new-output {
  background: rgba(16, 185, 129, 0.12);
  padding: 3px 6px;
  border-radius: 4px;
}

.console-step-tag {
  font-size: 10px;
  color: var(--text-muted);
}

/* CENTER COLUMN: Flowchart Visualizer + Memory & Variables */
.center-split {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.flow-canvas-wrapper {
  height: 46%;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  background: radial-gradient(circle at center, #131c31 0%, #0b0f19 100%);
  position: relative;
  overflow: hidden;
}

.flow-svg-container {
  flex: 1;
  overflow: auto;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 16px;
}

/* Memory & Variables Inspector */
.memory-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.memory-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.scope-card {
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid var(--border-highlight);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.scope-header {
  padding: 7px 12px;
  background: rgba(30, 41, 59, 0.7);
  border-bottom: 1px solid var(--border-color);
  font-size: 11.5px;
  font-weight: 700;
  font-family: var(--font-mono);
  color: #93c5fd;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.scope-header.active-frame {
  background: rgba(99, 102, 241, 0.2);
  color: #c7d2fe;
}

.var-list {
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.var-item {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: all 0.2s ease;
}

.var-item.var-changed {
  border-color: var(--accent-success);
  background: rgba(16, 185, 129, 0.09);
  box-shadow: 0 0 12px rgba(16, 185, 129, 0.15);
}

.var-item.var-new {
  border-color: var(--accent-secondary);
  background: rgba(6, 182, 212, 0.1);
}

.var-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.var-name-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.var-name {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 13.5px;
  color: #f1f5f9;
}

.var-type {
  font-size: 10px;
  font-family: var(--font-mono);
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(148, 163, 184, 0.15);
  color: var(--text-secondary);
}

.var-badge-change {
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  text-transform: uppercase;
}

.var-badge-change.new {
  background: rgba(6, 182, 212, 0.2);
  color: #22d3ee;
}

.var-badge-change.updated {
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
}

.var-value-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 13px;
}

.var-prev-val {
  color: var(--text-muted);
  text-decoration: line-through;
  font-size: 12px;
}

.var-arrow {
  color: var(--accent-success);
  font-size: 12px;
}

.var-curr-val {
  color: #38bdf8;
  font-weight: 600;
  word-break: break-all;
}

/* Visual Array Cells for Lists */
.array-cells {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}

.array-cell {
  background: var(--bg-input);
  border: 1px solid var(--border-highlight);
  border-radius: 4px;
  min-width: 36px;
  padding: 4px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.array-cell.active-index {
  border-color: var(--accent-warning);
  background: rgba(245, 158, 11, 0.18);
}

.array-cell-idx {
  font-size: 9px;
  color: var(--text-muted);
  font-family: var(--font-mono);
}

.array-cell-val {
  font-size: 12px;
  font-family: var(--font-mono);
  color: var(--text-primary);
  font-weight: 600;
}

/* RIGHT COLUMN: AI Tutor & Step-by-Step Explanation Panel */
.tutor-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.depth-selector {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  background: var(--bg-input);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.depth-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
  padding: 6px 4px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.depth-btn.active {
  background: var(--accent-primary);
  color: white;
}

.step-hero-card {
  background: linear-gradient(145deg, rgba(30, 41, 59, 0.9), rgba(15, 23, 42, 0.95));
  border: 1px solid rgba(99, 102, 241, 0.35);
  border-radius: var(--radius-lg);
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
}

.step-hero-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.event-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 99px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  background: rgba(99, 102, 241, 0.2);
  color: #a5b4fc;
}

.step-line-badge {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--text-secondary);
}

.step-code-preview {
  background: var(--bg-app);
  border-left: 3px solid var(--accent-primary);
  padding: 8px 10px;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 12.5px;
  color: #e2e8f0;
  overflow-x: auto;
}

.explanation-section {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.explanation-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #38bdf8;
  display: flex;
  align-items: center;
  gap: 6px;
}

.explanation-text {
  font-size: 13.5px;
  line-height: 1.55;
  color: #e2e8f0;
}

.explanation-text code {
  font-family: var(--font-mono);
  font-size: 12px;
  background: rgba(15, 23, 42, 0.8);
  padding: 2px 5px;
  border-radius: 4px;
  color: #67e8f9;
}

.eval-breakdown-box {
  background: rgba(15, 23, 42, 0.7);
  border: 1px dashed var(--border-highlight);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  font-family: var(--font-mono);
  font-size: 12px;
  color: #fde68a;
  margin-top: 4px;
}

/* Interactive Prediction Quiz Card */
.quiz-card {
  background: rgba(168, 85, 247, 0.12);
  border: 1px solid rgba(168, 85, 247, 0.45);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.quiz-options {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.quiz-option-btn {
  text-align: left;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-input);
  border: 1px solid var(--border-highlight);
  color: var(--text-primary);
  font-size: 12.5px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.quiz-option-btn:hover {
  border-color: var(--accent-purple);
  background: rgba(168, 85, 247, 0.15);
}

