class PythonFlowTracer {
  constructor() {
    this.maxSteps = 250;
  }

  trace(sourceCode, bigPictureNote = "") {
    const rawLines = sourceCode.replace(/\r\n/g, "\n").split("\n");
    const statements = this.parseLines(rawLines);
    const cfg = this.buildControlFlowGraph(statements);

    const steps = [];
    const stdout = [];
    const functions = {};
    const callStack = [
      {
        frameName: "Global Frame (main)",
        vars: {},
        prevVars: {}
      }
    ];

    // Step 0 / Startup Step: Explain what happens when the code starts executing!
    const firstExecutableLine = statements.length > 0 ? statements[0].line : 1;
    const firstCodeText = rawLines[firstExecutableLine - 1] ? rawLines[firstExecutableLine - 1].trim() : "";
    steps.push({
      stepIndex: 1,
      line: firstExecutableLine,
      nextLine: firstExecutableLine,
      codeText: firstCodeText,
      eventType: "PROGRAM_START",
      scopes: this.snapshotScopes(callStack, null),
      evalBreakdown: `Program Startup -> Creating Global Memory Frame & placing Instruction Pointer at Line ${firstExecutableLine}`,
      branchResult: null,
      loopMechanics: null,
      conditionMechanics: null,
      functionMechanics: null,
      stdout: [],
      explanations: {
        eli5: `Welcome! Before running any math or logic, Python sets up an empty desk called the **Global Frame** to hold your variables, and points its finger at **Line ${firstExecutableLine}** to begin reading from top to bottom.`,
        beginner: `**Program Startup**: Python initializes the \`Global Frame (main)\` in memory (currently empty) and positions the execution pointer at the first executable statement on **Line ${firstExecutableLine}** (\`${firstCodeText}\`).`,
        deep: `Interpreter initializes the module-level global namespace dictionary and sets the frame instruction pointer to the first AST statement at line ${firstExecutableLine}.`,
        whyItHappened: `Python always starts executing a script from the top-most statement (skipping blank lines and comments) and works downward unless a loop, branch, or function call redirects it.`,
        howNextLineDecided: `The program starts at **Line ${firstExecutableLine}** because it is the very first instruction in the file.`,
        seniorMentorNote: bigPictureNote || `Let's walk through this program together line by line. Watch how each line updates the variables in memory and how Python decides where to go next!`
      },
      quiz: null
    });

    try {
      this.executeBlock(statements, callStack, functions, steps, stdout);
    } catch (err) {
      steps.push({
        stepIndex: steps.length + 1,
        line: err.line || 1,
        nextLine: null,
        codeText: rawLines[(err.line || 1) - 1] || "",
        eventType: "ERROR",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `Runtime Error: ${err.message}`,
        branchResult: null,
        loopMechanics: null,
        conditionMechanics: null,
        functionMechanics: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Oops! Python ran into an error on line ${err.line || 1}: ${err.message}`,
          beginner: `Execution stopped on line ${err.line || 1} because of: ${err.message}`,
          deep: `Exception raised during statement evaluation: ${err.message}`,
          whyItHappened: `Check syntax or variable names on line ${err.line || 1}.`,
          howNextLineDecided: `Execution halted due to an unhandled error.`,
          whatNext: `Execution halted due to error.`
        },
        quiz: null
      });
    }

    // Post-process steps to populate exact Next Line Decision explanations, Execution Order history, and Quizzes
    for (let i = 0; i < steps.length; i++) {
      const cur = steps[i];
      const nextStep = i + 1 < steps.length ? steps[i + 1] : null;
      cur.nextLine = nextStep ? nextStep.line : null;

      if (!cur.explanations.howNextLineDecided) {
        cur.explanations.howNextLineDecided = this.explainNextLineDecision(cur, nextStep);
      }

      cur.explanations.whatNext = nextStep
        ? `Next (**Step ${nextStep.stepIndex}**), Python moves to **Line ${nextStep.line}** (\`${nextStep.codeText.trim()}\`) to ${this.describeUpcomingAction(nextStep)}.`
        : `🎉 **Program Complete!** All instructions have finished executing. Check the **Final Answer & Variable Timeline** tab to see how every variable evolved from start to finish!`;

      cur.quiz = this.generateQuizForStep(cur, nextStep);
    }

    const variableTimeline = this.buildVariableTimeline(steps);

    return {
      rawLines,
      steps,
      cfg,
      variableTimeline
    };
  }

  explainNextLineDecision(cur, nextStep) {
    if (!nextStep) {
      return `There are no more statements left in the program, so Python finishes execution.`;
    }
    if (cur.eventType === "PROGRAM_START") {
      return `Python begins by executing **Line ${nextStep.line}** first because code runs top-to-bottom.`;
    }
    if (cur.eventType === "CONDITION") {
      if (cur.branchResult === true) {
        return `Because the condition on Line ${cur.line} evaluated to **True**, Python steps **inside** the indented block at **Line ${nextStep.line}**.`;
      } else {
        return `Because the condition on Line ${cur.line} evaluated to **False**, Python **skips** the indented block and jumps directly to **Line ${nextStep.line}**.`;
      }
    }
    if (cur.eventType === "LOOP_ITER") {
      return `The loop is active, so Python enters the indented loop body starting at **Line ${nextStep.line}**.`;
    }
    if (cur.eventType === "LOOP_END") {
      return `The loop has finished all iterations, so Python jumps past the loop body to the next statement after the loop (**Line ${nextStep.line}**).`;
    }
    if (cur.eventType === "FUNC_CALL") {
      return `A function was called! Python pauses the caller line and jumps to the first line inside the function body (**Line ${nextStep.line}**).`;
    }
    if (cur.eventType === "RETURN") {
      return `\`return\` hands the result back to the caller, so Python jumps back to **Line ${nextStep.line}** where the function was called.`;
    }
    if (nextStep.line < cur.line) {
      return `We reached the bottom of the loop body on Line ${cur.line}, so Python **loops back up** to the loop header on **Line ${nextStep.line}** for the next check!`;
    }
    return `Normal sequential flow: after finishing Line ${cur.line}, Python moves straight down to the next statement on **Line ${nextStep.line}**.`;
  }

  buildVariableTimeline(steps) {
    const history = [];
    steps.forEach((s) => {
      const activeScope = s.scopes[s.scopes.length - 1];
      if (!activeScope) return;
      activeScope.variables.forEach((v) => {
        if (v.status === "new" || v.status === "updated") {
          history.push({
            stepIndex: s.stepIndex,
            line: s.line,
            frameName: activeScope.frameName,
            varName: v.name,
            prevVal: v.prevFormattedValue,
            newVal: v.formattedValue,
            status: v.status,
            codeText: s.codeText,
            evalBreakdown: s.evalBreakdown
          });
        }
      });
    });
    return history;
  }

  parseLines(rawLines) {
    const items = [];
    for (let i = 0; i < rawLines.length; i++) {
      const raw = rawLines[i];
      const strippedComment = this.stripInlineComment(raw);
      const trimmed = strippedComment.trim();
      if (!trimmed) continue;
      const indent = raw.match(/^\s*/)[0].length;
      items.push({
        line: i + 1,
        indent,
        text: trimmed,
        raw: raw
      });
    }
    return this.buildASTBlock(items, 0, items.length > 0 ? items[0].indent : 0).nodes;
  }

  stripInlineComment(line) {
    let inSingle = false;
    let inDouble = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (ch === "#" && !inSingle && !inDouble) {
        return line.slice(0, i);
      }
    }
    return line;
  }

  buildASTBlock(items, startIdx, baseIndent) {
    const nodes = [];
    let i = startIdx;

    while (i < items.length) {
      const item = items[i];
      if (item.indent < baseIndent) break;

      if (item.text.startsWith("if ") && item.text.endsWith(":")) {
        const branches = [];
        const cond = item.text.slice(3, -1).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        branches.push({
          type: "if",
          line: item.line,
          text: item.text,
          condition: cond,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;

        while (i < items.length && items[i].indent === item.indent) {
          const cur = items[i];
          if (cur.text.startsWith("elif ") && cur.text.endsWith(":")) {
            const elifCond = cur.text.slice(5, -1).trim();
            const elifBody = this.parseChildSuite(items, i + 1, cur.indent);
            branches.push({
              type: "elif",
              line: cur.line,
              text: cur.text,
              condition: elifCond,
              body: elifBody.nodes
            });
            i = elifBody.nextIdx;
          } else if (cur.text === "else:") {
            const elseBody = this.parseChildSuite(items, i + 1, cur.indent);
            branches.push({
              type: "else",
              line: cur.line,
              text: cur.text,
              condition: null,
              body: elseBody.nodes
            });
            i = elseBody.nextIdx;
            break;
          } else {
            break;
          }
        }
        nodes.push({
          kind: "IF_CHAIN",
          line: item.line,
          text: item.text,
          branches
        });
      } else if (item.text.startsWith("for ") && item.text.endsWith(":")) {
        const header = item.text.slice(4, -1).trim();
        const inIdx = header.indexOf(" in ");
        const iterVar = header.slice(0, inIdx).trim();
        const iterExpr = header.slice(inIdx + 4).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "FOR",
          line: item.line,
          text: item.text,
          iterVar,
          iterExpr,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("while ") && item.text.endsWith(":")) {
        const condition = item.text.slice(6, -1).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "WHILE",
          line: item.line,
          text: item.text,
          condition,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("def ") && item.text.endsWith(":")) {
        const match = item.text.match(/^def\s+([a-zA-Z_]\w*)\s*\((.*)\)\s*:$/);
        const funcName = match ? match[1] : "func";
        const params = match && match[2].trim()
          ? match[2].split(",").map((s) => s.trim())
          : [];
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "DEF",
          line: item.line,
          text: item.text,
          funcName,
          params,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else {
        nodes.push({
          kind: "STMT",
          line: item.line,
          text: item.text
        });
        i++;
      }
    }

    return { nodes, nextIdx: i };
  }

  parseChildSuite(items, nextIdx, parentIndent) {
    if (nextIdx >= items.length || items[nextIdx].indent <= parentIndent) {
      return { nodes: [], nextIdx };
    }
    return this.buildASTBlock(items, nextIdx, items[nextIdx].indent);
  }

  executeBlock(nodes, callStack, functions, steps, stdout) {
    for (const node of nodes) {
      if (steps.length >= this.maxSteps) break;
      const ret = this.executeNode(node, callStack, functions, steps, stdout);
      if (ret && ret.returned) {
        return ret;
      }
    }
    return null;
  }

  analyzeConditionDetails(condExpr, scopeVars, functions, callStack, steps, stdout, line) {
    const ops = ["==", "!=", ">=", "<=", ">", "<"];
    for (const op of ops) {
      const idx = condExpr.indexOf(op);
      if (idx !== -1) {
        const leftRaw = condExpr.slice(0, idx).trim();
        const rightRaw = condExpr.slice(idx + op.length).trim();
        const leftVal = this.evalExpr(leftRaw, scopeVars, functions, callStack, steps, stdout, line);
        const rightVal = this.evalExpr(rightRaw, scopeVars, functions, callStack, steps, stdout, line);
        const finalBool = Boolean(this.evalExpr(condExpr, scopeVars, functions, callStack, steps, stdout, line));
        return {
          leftExpr: leftRaw,
          leftSub: this.substituteVarsInExpr(leftRaw, scopeVars),
          leftVal: this.formatVal(leftVal),
          operator: op,
          rightExpr: rightRaw,
          rightSub: this.substituteVarsInExpr(rightRaw, scopeVars),
          rightVal: this.formatVal(rightVal),
          result: finalBool
        };
      }
    }
    const finalBool = Boolean(this.evalExpr(condExpr, scopeVars, functions, callStack, steps, stdout, line));
    return {
      leftExpr: condExpr,
      leftSub: this.substituteVarsInExpr(condExpr, scopeVars),
      leftVal: this.formatVal(finalBool),
      operator: "is",
      rightExpr: "Truthy",
      rightSub: "Truthy",
      rightVal: "True",
      result: finalBool
    };
  }

  executeNode(node, callStack, functions, steps, stdout) {
    const activeFrame = callStack[callStack.length - 1];

    if (node.kind === "DEF") {
      functions[node.funcName] = node;
      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: node.text,
        eventType: "FUNC_DEF",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `Registered function ${node.funcName}(${node.params.join(", ")}) in memory`,
        branchResult: null,
        loopMechanics: null,
        conditionMechanics: null,
        functionMechanics: {
          type: "DEF",
          funcName: node.funcName,
          params: node.params,
          note: `Python stores the function definition for \`${node.funcName}\`. Notice that Python skips over the indented lines inside the function for now—they only run when \`${node.funcName}(...)\` is called!`
        },
        stdout: [...stdout],
        explanations: {
          eli5: `Python reads the recipe name \`${node.funcName}\` and saves it in its cookbook for later. It does NOT run the lines inside yet!`,
          beginner: `**Function Definition (\`def\`)**: Registers function \`${node.funcName}\` with parameters \`(${node.params.join(", ")})\`. Python skips the indented body until the function is actually called.`,
          deep: `Compiles function body and binds function object \`${node.funcName}\` in the active namespace without invoking it.`,
          whyItHappened: `A \`def\` statement only defines how a function works; the code inside waits until a function call happens.`
        }
      });
      return null;
    }

    if (node.kind === "IF_CHAIN") {
      for (const branch of node.branches) {
        if (branch.type === "else") {
          steps.push({
            stepIndex: steps.length + 1,
            line: branch.line,
            codeText: branch.text,
            eventType: "CONDITION",
            scopes: this.snapshotScopes(callStack, null),
            evalBreakdown: `All earlier if/elif conditions were False -> entering else block`,
            branchResult: true,
            loopMechanics: null,
            conditionMechanics: {
              leftExpr: "Prior if/elif branches",
              leftSub: "All False",
              leftVal: "False",
              operator: "->",
              rightExpr: "else:",
              rightSub: "Fallback",
              rightVal: "Run Block",
              result: true
            },
            functionMechanics: null,
            stdout: [...stdout],
            explanations: {
              eli5: `Since none of the earlier \`if\` or \`elif\` questions were true, Python automatically takes the \`else:\` backup door!`,
              beginner: `All preceding \`if\`/\`elif\` conditions evaluated to \`False\`, so Python enters the default \`else:\` branch.`,
              deep: `Exhausted conditional predicates in \`if/elif\` chain; executing fallback \`else\` suite.`,
              whyItHappened: `The \`else\` block acts as a catch-all when every condition above it was \`False\`.`
            }
          });
          return this.executeBlock(branch.body, callStack, functions, steps, stdout);
        } else {
          const condInfo = this.analyzeConditionDetails(
            branch.condition,
            activeFrame.vars,
            functions,
            callStack,
            steps,
            stdout,
            branch.line
          );
          const val = condInfo.result;
          const substituted = this.substituteVarsInExpr(branch.condition, activeFrame.vars);

          steps.push({
            stepIndex: steps.length + 1,
            line: branch.line,
            codeText: branch.text,
            eventType: "CONDITION",
            scopes: this.snapshotScopes(callStack, null),
            evalBreakdown: `${branch.condition}  ==>  ${substituted}  ==>  ${condInfo.leftVal} ${condInfo.operator} ${condInfo.rightVal}  ==>  ${val ? "True" : "False"}`,
            branchResult: val,
            loopMechanics: null,
            conditionMechanics: condInfo,
            functionMechanics: null,
            stdout: [...stdout],
            explanations: {
              eli5: val
                ? `Python plugs in the current numbers (\`${substituted}\`) and asks: Is \`${condInfo.leftVal} ${condInfo.operator} ${condInfo.rightVal}\`? **YES (True)!** So Python steps inside the indented block.`
                : `Python plugs in the current numbers (\`${substituted}\`) and asks: Is \`${condInfo.leftVal} ${condInfo.operator} ${condInfo.rightVal}\`? **NO (False)!** So Python skips over the indented lines below it.`,
              beginner: `**Condition Check**: Python evaluates \`${branch.condition}\` by substituting current values (\`${substituted}\` $\\rightarrow$ \`${condInfo.leftVal} ${condInfo.operator} ${condInfo.rightVal}\`), which is **${val ? "True" : "False"}**. ${val ? "Therefore, Python enters this branch." : "Therefore, Python skips this branch."}`,
              deep: `Relational expression \`${branch.condition}\` evaluated left operand (\`${condInfo.leftVal}\`) and right operand (\`${condInfo.rightVal}\`) with operator \`${condInfo.operator}\`, yielding boolean \`${val ? "True" : "False"}\`.`,
              whyItHappened: `In Python, an \`if\`/\`elif\` block only runs when its condition evaluates to \`True\`.`
            }
          });
          if (val) {
            return this.executeBlock(branch.body, callStack, functions, steps, stdout);
          }
        }
      }
      return null;
    }

    if (node.kind === "FOR") {
      const iterable = this.evalExpr(node.iterExpr, activeFrame.vars, functions, callStack, steps, stdout, node.line);
      const listItems = Array.isArray(iterable) ? iterable : [];

      for (let idx = 0; idx < listItems.length; idx++) {
        if (steps.length >= this.maxSteps) break;
        const itemVal = listItems[idx];
        const prevVal = activeFrame.vars[node.iterVar];
        const isNew = !(node.iterVar in activeFrame.vars);
        activeFrame.prevVars[node.iterVar] = prevVal;
        activeFrame.vars[node.iterVar] = itemVal;

        steps.push({
          stepIndex: steps.length + 1,
          line: node.line,
          codeText: node.text,
          eventType: "LOOP_ITER",
          scopes: this.snapshotScopes(callStack, {
            name: node.iterVar,
            status: isNew ? "new" : "updated",
            prevValue: prevVal
          }),
          evalBreakdown: `Loop Pass ${idx + 1} of ${listItems.length}: ${node.iterVar} = ${this.formatVal(itemVal)} (from index ${idx})`,
          branchResult: true,
          loopMechanics: {
            loopType: "for",
            iterVar: node.iterVar,
            iterExpr: node.iterExpr,
            currentIndex: idx,
            totalItems: listItems.length,
            items: listItems.map((v) => this.formatVal(v)),
            currentValue: this.formatVal(itemVal)
          },
          conditionMechanics: null,
          functionMechanics: null,
          stdout: [...stdout],
          explanations: {
            eli5: `**Loop Pass #${idx + 1} of ${listItems.length}**: Python moves its pointer to position \`[${idx}]\` in \`${node.iterExpr}\`, grabs the value \`${this.formatVal(itemVal)}\`, and stores it in \`${node.iterVar}\`. Now it will run the indented loop body!`,
            beginner: `**For-Loop Internals (Iteration ${idx + 1}/${listItems.length})**: Python automatically fetches element \`[${idx}]\` (\`${this.formatVal(itemVal)}\`) from \`${node.iterExpr}\` and assigns \`${node.iterVar} = ${this.formatVal(itemVal)}\`. Then it enters the loop body.`,
            deep: `The \`for\` loop iterator advances to index \`${idx}\`, binds target \`${node.iterVar} = ${this.formatVal(itemVal)}\` in \`${activeFrame.frameName}\`, and transfers control to the loop suite.`,
            whyItHappened: `A \`for\` loop automatically steps through each item of sequence \`${node.iterExpr}\` one by one from left to right.`
          }
        });

        const ret = this.executeBlock(node.body, callStack, functions, steps, stdout);
        if (ret && ret.returned) return ret;
      }

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: node.text,
        eventType: "LOOP_END",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `For-loop completed all ${listItems.length} items -> exiting loop`,
        branchResult: false,
        loopMechanics: {
          loopType: "for",
          iterVar: node.iterVar,
          iterExpr: node.iterExpr,
          currentIndex: listItems.length,
          totalItems: listItems.length,
          items: listItems.map((v) => this.formatVal(v)),
          currentValue: "DONE"
        },
        conditionMechanics: null,
        functionMechanics: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python looks back at \`${node.iterExpr}\` and sees there are no more items left! So the \`for\` loop is officially finished, and Python jumps past the loop.`,
          beginner: `**For-Loop Finished**: All ${listItems.length} elements in \`${node.iterExpr}\` have been visited. Python exits the loop and continues with the first line after the indented block.`,
          deep: `Iterator raised internal \`StopIteration\` after ${listItems.length} elements; loop terminates.`,
          whyItHappened: `A \`for\` loop stops automatically once every item in the sequence has been processed.`
        }
      });
      return null;
    }

    if (node.kind === "WHILE") {
      let guard = 0;
      while (guard < 100 && steps.length < this.maxSteps) {
        guard++;
        const condInfo = this.analyzeConditionDetails(
          node.condition,
          activeFrame.vars,
          functions,
          callStack,
          steps,
          stdout,
          node.line
        );
        const condVal = condInfo.result;
        const substituted = this.substituteVarsInExpr(node.condition, activeFrame.vars);

        steps.push({
          stepIndex: steps.length + 1,
          line: node.line,
          codeText: node.text,
          eventType: condVal ? "LOOP_ITER" : "LOOP_END",
          scopes: this.snapshotScopes(callStack, null),
          evalBreakdown: `${node.condition}  ==>  ${substituted}  ==>  ${condVal ? "True (Enter Loop Pass #" + guard + ")" : "False (Exit While Loop)"}`,
          branchResult: condVal,
          loopMechanics: {
            loopType: "while",
            condition: node.condition,
            substituted,
            iteration: guard,
            isContinuing: condVal
          },
          conditionMechanics: condInfo,
          functionMechanics: null,
          stdout: [...stdout],
          explanations: {
            eli5: condVal
              ? `**While-Loop Check #${guard}**: Python checks if \`${substituted}\` is still true. Yes (\`True\`)! So it runs the indented loop lines again.`
              : `**While-Loop Check #${guard}**: Python checks if \`${substituted}\` is true. Not anymore (\`False\`)! So the loop stops and Python moves on.`,
            beginner: condVal
              ? `**While-Loop Iteration #${guard}**: Condition \`${node.condition}\` (\`${substituted}\`) evaluated to **True**, so Python enters the loop body.`
              : `**While-Loop Terminated**: Condition \`${node.condition}\` (\`${substituted}\`) evaluated to **False**, so Python exits the loop.`,
            deep: `While-loop predicate \`${node.condition}\` evaluated to \`${condVal ? "True" : "False"}\` on check #${guard}.`,
            whyItHappened: `Before every single pass, a \`while\` loop re-tests its condition using the latest variable values.`
          }
        });

        if (!condVal) break;
        const ret = this.executeBlock(node.body, callStack, functions, steps, stdout);
        if (ret && ret.returned) return ret;
      }
      return null;
    }

    if (node.kind === "STMT") {
      return this.executeSimpleStatement(node, callStack, functions, steps, stdout);
    }

    return null;
  }

  executeSimpleStatement(node, callStack, functions, steps, stdout) {
    const activeFrame = callStack[callStack.length - 1];
    const text = node.text;

    // 1. Return statement
    if (text === "return" || text.startsWith("return ")) {
      const expr = text === "return" ? "None" : text.slice(7).trim();
      const retVal = expr === "None" ? null : this.evalExpr(expr, activeFrame.vars, functions, callStack, steps, stdout, node.line);
      const substituted = this.substituteVarsInExpr(expr, activeFrame.vars);

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "RETURN",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `return ${expr} (${substituted})  ==>  Hands back ${this.formatVal(retVal)} to caller`,
        branchResult: null,
        loopMechanics: null,
        conditionMechanics: null,
        functionMechanics: {
          type: "RETURN",
          frameName: activeFrame.frameName,
          returnExpr: expr,
          returnValue: this.formatVal(retVal),
          note: `\`return\` packages up the result \`${this.formatVal(retVal)}\`, destroys this function's temporary local memory frame (\`${activeFrame.frameName}\`), and sends \`${this.formatVal(retVal)}\` back to the line that called it!`
        },
        stdout: [...stdout],
        explanations: {
          eli5: `The function is done! It hands back the answer \`${this.formatVal(retVal)}\` to the line that called it, and cleans up its temporary workspace.`,
          beginner: `**Return Statement**: Evaluates \`${expr}\` to \`${this.formatVal(retVal)}\`, exits \`${activeFrame.frameName}\`, and sends \`${this.formatVal(retVal)}\` back as the result of the function call.`,
          deep: `Pops activation frame \`${activeFrame.frameName}\` from the call stack and returns value \`${this.formatVal(retVal)}\` to caller expression context.`,
          whyItHappened: `\`return\` immediately stops the function and sends a computed value back to the caller.`
        }
      });

      return { returned: true, value: retVal };
    }

    // 2. Print statement
    if (text.startsWith("print(") && text.endsWith(")")) {
      const inner = text.slice(6, -1).trim();
      const args = this.splitTopLevelArgs(inner);
      const evaluatedArgs = args.map((arg) =>
        this.evalExpr(arg, activeFrame.vars, functions, callStack, steps, stdout, node.line)
      );
      const outputLine = evaluatedArgs
        .map((v) => (typeof v === "string" ? v : this.formatVal(v)))
        .join(" ");

      stdout.push({
        stepIndex: steps.length + 1,
        line: node.line,
        text: outputLine
      });

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "PRINT",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `print(${inner})  ==>  Console Output: "${outputLine}"`,
        branchResult: null,
        loopMechanics: null,
        conditionMechanics: null,
        functionMechanics: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python looks up the current values of the items inside \`print(...)\` and displays **\`${outputLine}\`** in the Console Output box!`,
          beginner: `**Console Output (\`print\`)**: Evaluates each argument inside \`print(${inner})\` and writes \`"${outputLine}"\` to standard output.`,
          deep: `Evaluates argument expressions, converts objects to strings, and flushes \`"${outputLine}\\n"\` to \`stdout\`.`,
          whyItHappened: `\`print()\` does not change any variables in memory; it simply displays values to the user.`
        }
      });
      return null;
    }

    // 3. List .append() method
    const appendMatch = text.match(/^([a-zA-Z_]\w*)\.append\((.*)\)$/);
    if (appendMatch) {
      const listName = appendMatch[1];
      const argExpr = appendMatch[2].trim();
      const itemVal = this.evalExpr(argExpr, activeFrame.vars, functions, callStack, steps, stdout, node.line);
      const currentList = Array.isArray(activeFrame.vars[listName]) ? [...activeFrame.vars[listName]] : [];
      const prevCopy = [...currentList];
      currentList.push(itemVal);
      activeFrame.prevVars[listName] = prevCopy;
      activeFrame.vars[listName] = currentList;

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "ASSIGN",
        scopes: this.snapshotScopes(callStack, {
          name: listName,
          status: "updated",
          prevValue: prevCopy
        }),
        evalBreakdown: `${listName}.append(${this.formatVal(itemVal)})  ==>  ${this.formatVal(currentList)}`,
        branchResult: null,
        loopMechanics: null,
        conditionMechanics: null,
        functionMechanics: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python tacks \`${this.formatVal(itemVal)}\` onto the end of the list \`${listName}\`!`,
          beginner: `Mutates list \`${listName}\` in-place by appending \`${this.formatVal(itemVal)}\` at index ${currentList.length - 1}.`,
          deep: `Invokes \`list.append\` method on \`${listName}\`, growing the list object to length ${currentList.length}.`,
          whyItHappened: `\`.append()\` adds a new element to the end of an existing list.`
        }
      });
      return null;
    }

    // 4. Augmented assignment (+=, -=, *=)
    const augMatch = text.match(/^([a-zA-Z_]\w*)\s*(\+=|-=|\*=)\s*(.+)$/);
    if (augMatch) {
      const varName = augMatch[1];
      const op = augMatch[2][0];
      const rhsExpr = augMatch[3].trim();
      const fullExpr = `${varName} ${op} (${rhsExpr})`;
      const prevVal = activeFrame.vars[varName];
      const newVal = this.evalExpr(fullExpr, activeFrame.vars, functions, callStack, steps, stdout, node.line);
      const substituted = `${this.formatVal(prevVal)} ${op} ${this.substituteVarsInExpr(rhsExpr, activeFrame.vars)}`;

      activeFrame.prevVars[varName] = prevVal;
      activeFrame.vars[varName] = newVal;

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "ASSIGN",
        scopes: this.snapshotScopes(callStack, {
          name: varName,
          status: "updated",
          prevValue: prevVal
        }),
        evalBreakdown: `${varName} = ${substituted}  ==>  ${this.formatVal(newVal)}`,
        branchResult: null,
        loopMechanics: null,
        conditionMechanics: null,
        functionMechanics: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python takes the old value of \`${varName}\` (\`${this.formatVal(prevVal)}\`), updates it using \`${op}\`, and stores the new result \`${this.formatVal(newVal)}\` back into \`${varName}\`!`,
          beginner: `Updates \`${varName}\` from \`${this.formatVal(prevVal)}\` to \`${this.formatVal(newVal)}\` by computing \`${substituted}\`.`,
          deep: `Evaluates augmented assignment \`${augMatch[2]}\` on \`${varName}\` and rebinds the identifier to \`${this.formatVal(newVal)}\`.`,
          whyItHappened: `\`${augMatch[2]}\` is shorthand for \`${varName} = ${varName} ${op} ${rhsExpr}\`.`
        }
      });
      return null;
    }

    // 5. Standard assignment: varName = expr
    const assignMatch = text.match(/^([a-zA-Z_]\w*)\s*=\s*(.+)$/);
    if (assignMatch && !text.includes("==")) {
      const varName = assignMatch[1];
      const rhsExpr = assignMatch[2].trim();
      const prevVal = activeFrame.vars[varName];
      const isNew = !(varName in activeFrame.vars);
      const substituted = this.substituteVarsInExpr(rhsExpr, activeFrame.vars);
      const newVal = this.evalExpr(rhsExpr, activeFrame.vars, functions, callStack, steps, stdout, node.line);

      activeFrame.prevVars[varName] = prevVal;
      activeFrame.vars[varName] = newVal;

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "ASSIGN",
        scopes: this.snapshotScopes(callStack, {
          name: varName,
          status: isNew ? "new" : "updated",
          prevValue: prevVal
        }),
        evalBreakdown:
          substituted !== rhsExpr
            ? `${rhsExpr}  ==>  ${substituted}  ==>  ${this.formatVal(newVal)}   (stored in ${varName})`
            : `${varName}  <--  ${this.formatVal(newVal)}`,
        branchResult: null,
        loopMechanics: null,
        conditionMechanics: null,
        functionMechanics: null,
        stdout: [...stdout],
        explanations: {
          eli5: isNew
            ? `Python creates a brand-new labeled box in memory called **\`${varName}\`** and puts **\`${this.formatVal(newVal)}\`** inside it!`
            : `Python calculates the right side first (\`${substituted}\` = \`${this.formatVal(newVal)}\`), then replaces the old value in **\`${varName}\`** (was \`${this.formatVal(prevVal)}\`, now \`${this.formatVal(newVal)}\`).`,
          beginner: isNew
            ? `**New Variable Created**: Python evaluates the right-hand side (\`${rhsExpr}\` $\\rightarrow$ \`${this.formatVal(newVal)}\`) and stores it in a new variable \`${varName}\` (type \`${this.getPythonType(newVal)}\`).`
            : `**Variable Updated**: Python evaluates \`${rhsExpr}\` using current memory values (\`${substituted}\` $\\rightarrow$ \`${this.formatVal(newVal)}\`) and overwrites \`${varName}\` from \`${this.formatVal(prevVal)}\` to \`${this.formatVal(newVal)}\`.`,
          deep: `Evaluates RHS expression \`${rhsExpr}\` to object \`${this.formatVal(newVal)}\` (\`${this.getPythonType(newVal)}\`) and binds identifier \`${varName}\` in \`${activeFrame.frameName}\`.`,
          whyItHappened: `Rule of \`=\` in Python: Always calculate the **Right-Hand Side** completely first, then store that answer in the variable name on the **Left-Hand Side**.`
        }
      });
      return null;
    }

    return null;
  }

  evalExpr(expr, scopeVars, functions, callStack, steps, stdout, lineNum) {
    const trimmed = expr.trim();

    // Check range(...)
    const rangeMatch = trimmed.match(/^range\((.+)\)$/);
    if (rangeMatch) {
      const parts = this.splitTopLevelArgs(rangeMatch[1]).map((a) =>
        Number(this.evalExpr(a, scopeVars, functions, callStack, steps, stdout, lineNum))
      );
      let start = 0,
        stop = 0,
        step = 1;
      if (parts.length === 1) {
        stop = parts[0];
      } else if (parts.length === 2) {
        start = parts[0];
        stop = parts[1];
      } else if (parts.length >= 3) {
        start = parts[0];
        stop = parts[1];
        step = parts[2] || 1;
      }
      const arr = [];
      if (step > 0) {
        for (let v = start; v < stop; v += step) arr.push(v);
      } else if (step < 0) {
        for (let v = start; v > stop; v += step) arr.push(v);
      }
      return arr;
    }

    // Check len(...)
    const lenMatch = trimmed.match(/^len\((.+)\)$/);
    if (lenMatch) {
      const target = this.evalExpr(lenMatch[1], scopeVars, functions, callStack, steps, stdout, lineNum);
      return target && typeof target.length === "number" ? target.length : 0;
    }

    // Check user-defined function call: funcName(arg1, arg2)
    const callMatch = trimmed.match(/^([a-zA-Z_]\w*)\((.*)\)$/);
    if (callMatch && functions[callMatch[1]]) {
      const fnNode = functions[callMatch[1]];
      const rawArgs = callMatch[2].trim() ? this.splitTopLevelArgs(callMatch[2]) : [];
      const argVals = rawArgs.map((a) =>
        this.evalExpr(a, scopeVars, functions, callStack, steps, stdout, lineNum)
      );

      const newFrameVars = {};
      const mappings = [];
      fnNode.params.forEach((p, idx) => {
        newFrameVars[p] = argVals[idx];
        mappings.push({
          argExpr: rawArgs[idx] || "None",
          argVal: this.formatVal(argVals[idx]),
          paramName: p
        });
      });

      const newFrame = {
        frameName: `${fnNode.funcName}(${fnNode.params.map((p, i) => `${p}=${this.formatVal(argVals[i])}`).join(", ")})`,
        vars: newFrameVars,
        prevVars: {}
      };

      callStack.push(newFrame);

      steps.push({
        stepIndex: steps.length + 1,
        line: fnNode.line,
        codeText: fnNode.text,
        eventType: "FUNC_CALL",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `Function Call from Line ${lineNum}: ${fnNode.funcName}(${rawArgs.join(", ")}) -> ${newFrame.frameName}`,
        branchResult: null,
        loopMechanics: null,
        conditionMechanics: null,
        functionMechanics: {
          type: "CALL",
          funcName: fnNode.funcName,
          callerLine: lineNum,
          mappings,
          note: `Arguments from Line ${lineNum} are copied into the function's parameter variables inside a brand-new Call Stack Frame!`
        },
        stdout: [...stdout],
        explanations: {
          eli5: `**Calling Function \`${fnNode.funcName}\`**: Python pauses Line ${lineNum}, opens a fresh workspace for \`${fnNode.funcName}\`, and plugs your inputs into its parameters (${mappings.map((m) => `\`${m.paramName} = ${m.argVal}\``).join(", ")})!`,
          beginner: `**Function Call & Parameter Binding**: Line ${lineNum} called \`${fnNode.funcName}(${rawArgs.join(", ")})\`. Python pushes a new frame \`${newFrame.frameName}\` onto the Call Stack and binds each argument to its matching parameter.`,
          deep: `Pushes new stack frame for \`${fnNode.funcName}\`, binding formal parameters ${mappings.map((m) => `\`${m.paramName}=${m.argVal}\``).join(", ")} in local scope.`,
          whyItHappened: `When you call a function, Python passes the argument values into the function's parameters and runs the function's lines.`
        }
      });

      const res = this.executeBlock(fnNode.body, callStack, functions, steps, stdout);
      callStack.pop();
      return res && res.returned ? res.value : null;
    }

    // Replace Python operators/keywords for safe JS expression evaluation
    let jsExpr = trimmed
      .replace(/\/\//g, "___INTDIV___")
      .replace(/\band\b/g, "&&")
      .replace(/\bor\b/g, "||")
      .replace(/\bnot\s+/g, "!")
      .replace(/\bTrue\b/g, "true")
      .replace(/\bFalse\b/g, "false")
      .replace(/\bNone\b/g, "null");

    if (jsExpr.includes("___INTDIV___")) {
      const parts = jsExpr.split("___INTDIV___");
      if (parts.length === 2) {
        jsExpr = `Math.floor((${parts[0]}) / (${parts[1]}))`;
      }
    }

    const keys = Object.keys(scopeVars);
    const vals = keys.map((k) => scopeVars[k]);
    try {
      const fn = new Function(...keys, `return (${jsExpr});`);
      return fn(...vals);
    } catch (e) {
      throw { message: e.message, line: lineNum };
    }
  }

  substituteVarsInExpr(expr, scopeVars) {
    let result = expr;
    const sortedNames = Object.keys(scopeVars).sort((a, b) => b.length - a.length);
    for (const name of sortedNames) {
      const regex = new RegExp(`\\b${name}\\b`, "g");
      result = result.replace(regex, this.formatVal(scopeVars[name]));
    }
    return result;
  }

  splitTopLevelArgs(str) {
    if (!str.trim()) return [];
    const res = [];
    let current = "";
    let depth = 0;
    let inSingle = false;
    let inDouble = false;

    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[") depth++;
        else if (ch === ")" || ch === "]") depth--;
        else if (ch === "," && depth === 0) {
          res.push(current.trim());
          current = "";
          continue;
        }
      }
      current += ch;
    }
    if (current.trim()) res.push(current.trim());
    return res;
  }

  snapshotScopes(callStack, changedVarInfo) {
    return callStack.map((frame, frameIdx) => {
      const isTopFrame = frameIdx === callStack.length - 1;
      const variables = Object.keys(frame.vars).map((varName) => {
        const val = frame.vars[varName];
        const isChangedHere = isTopFrame && changedVarInfo && changedVarInfo.name === varName;
        return {
          name: varName,
          type: this.getPythonType(val),
          value: Array.isArray(val) ? [...val] : val,
          formattedValue: this.formatVal(val),
          prevFormattedValue:
            isChangedHere && changedVarInfo.prevValue !== undefined
              ? this.formatVal(changedVarInfo.prevValue)
              : null,
          status: isChangedHere ? changedVarInfo.status : "unchanged"
        };
      });
      return {
        frameName: frame.frameName,
        isActive: isTopFrame,
        variables
      };
    });
  }

  getPythonType(val) {
    if (val === null || val === undefined) return "NoneType";
    if (Array.isArray(val)) return "list";
    if (typeof val === "boolean") return "bool";
    if (typeof val === "number") return Number.isInteger(val) ? "int" : "float";
    if (typeof val === "string") return "str";
    return typeof val;
  }

  formatVal(val) {
    if (val === null || val === undefined) return "None";
    if (typeof val === "boolean") return val ? "True" : "False";
    if (typeof val === "string") return `"${val}"`;
    if (Array.isArray(val)) return `[${val.map((v) => this.formatVal(v)).join(", ")}]`;
    return String(val);
  }

  describeUpcomingAction(nextStep) {
    switch (nextStep.eventType) {
      case "ASSIGN":
        return "calculate the right-hand side and update a variable in memory";
      case "CONDITION":
        return "evaluate a condition to True or False and decide whether to enter the block";
      case "LOOP_ITER":
        return "advance the loop to the next iteration";
      case "LOOP_END":
        return "finish the loop and move past the indented block";
      case "PRINT":
        return "display values in the Console Output";
      case "FUNC_CALL":
        return "pass arguments into parameters and enter the function";
      case "RETURN":
        return "return the computed result back to the caller";
      default:
        return "execute the statement";
    }
  }

  generateQuizForStep(currentStep, nextStep) {
    if (!nextStep) return null;
    if (nextStep.eventType === "CONDITION") {
      return {
        question: `Prediction Challenge: On Line ${nextStep.line} (\`${nextStep.codeText}\`), what will the condition evaluate to?`,
        options: [
          { label: "True (Enter the indented block)", isCorrect: nextStep.branchResult === true },
          { label: "False (Skip the indented block)", isCorrect: nextStep.branchResult === false }
        ],
        explanation: nextStep.evalBreakdown
      };
    }
    if (nextStep.eventType === "ASSIGN") {
      const activeScope = nextStep.scopes[nextStep.scopes.length - 1];
      const changed = activeScope.variables.find((v) => v.status !== "unchanged");
      if (changed) {
        const correctVal = changed.formattedValue;
        const fake1 = typeof changed.value === "number" ? String(changed.value + 2) : `"None"`;
        const fake2 = typeof changed.value === "number" ? String(changed.value * 2 + 1) : `0`;
        const options = [
          { label: `${changed.name} = ${correctVal}`, isCorrect: true },
          { label: `${changed.name} = ${fake1}`, isCorrect: false },
          { label: `${changed.name} = ${fake2}`, isCorrect: false }
        ].sort(() => Math.random() - 0.5);
        return {
          question: `Prediction Challenge: After Line ${nextStep.line} (\`${nextStep.codeText}\`) runs, what will \`${changed.name}\` contain?`,
          options,
          explanation: nextStep.evalBreakdown
        };
      }
    }
    return null;
  }

  buildControlFlowGraph(statements) {
    const nodes = [];
    const edges = [];

    const addNode = (id, label, type, line) => {
      nodes.push({ id, label, type, line });
      return id;
    };

    const startId = addNode("start", "START PROGRAM", "start", 0);

    const buildList = (stmts, prevIds) => {
      let currentPrevs = prevIds;
      for (const s of stmts) {
        if (s.kind === "IF_CHAIN") {
          const exitIds = [];
          let condPrevIds = currentPrevs;
          for (const br of s.branches) {
            if (br.type === "else") {
              const bodyEnd = buildList(br.body, condPrevIds);
              exitIds.push(...bodyEnd);
              condPrevIds = [];
            } else {
              const cid = addNode(`L${br.line}`, `${br.type.toUpperCase()}: ${br.condition}`, "condition", br.line);
              condPrevIds.forEach((p) => edges.push({ from: p, to: cid }));
              const bodyEnd = buildList(br.body, [cid]);
              exitIds.push(...bodyEnd);
              condPrevIds = [cid];
            }
          }
          currentPrevs = [...exitIds, ...condPrevIds];
        } else if (s.kind === "FOR" || s.kind === "WHILE") {
          const label = s.kind === "FOR" ? `FOR ${s.iterVar} in ${s.iterExpr}` : `WHILE ${s.condition}`;
          const loopId = addNode(`L${s.line}`, label, "loop", s.line);
          currentPrevs.forEach((p) => edges.push({ from: p, to: loopId }));
          const bodyEnd = buildList(s.body, [loopId]);
          bodyEnd.forEach((b) => edges.push({ from: b, to: loopId, isBackEdge: true }));
          currentPrevs = [loopId];
        } else {
          const nid = addNode(
            `L${s.line}`,
            s.text.length > 28 ? s.text.slice(0, 26) + ".." : s.text,
            s.text.startsWith("print(") ? "output" : s.kind === "DEF" ? "func" : "stmt",
            s.line
          );
          currentPrevs.forEach((p) => edges.push({ from: p, to: nid }));
          currentPrevs = [nid];
        }
      }
      return currentPrevs;
    };

    const lastIds = buildList(statements, [startId]);
    const endId = addNode("end", "END PROGRAM", "end", 9999);
    lastIds.forEach((p) => edges.push({ from: p, to: endId }));

    return { nodes, edges };
  }
}

