/* Step 2 Additions: Execution Order Badges, Loop/Condition/Function Deep Visualizers & Variable History Table */

.exec-order-pill {
  font-size: 10px;
  font-family: var(--font-mono);
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(148, 163, 184, 0.12);
  color: #94a3b8;
  border: 1px solid rgba(148, 163, 184, 0.25);
}

.exec-order-pill.latest-step {
  background: rgba(99, 102, 241, 0.25);
  color: #c7d2fe;
  border-color: var(--accent-primary);
  font-weight: 700;
}

/* Mechanics Visual Cards (Loop, Condition, Function) */
.mechanics-card {
  background: linear-gradient(145deg, rgba(15, 23, 42, 0.92), rgba(30, 41, 59, 0.85));
  border: 1px solid var(--border-highlight);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mechanics-card.loop-card {
  border-color: rgba(6, 182, 212, 0.45);
}

.mechanics-card.cond-card {
  border-color: rgba(245, 158, 11, 0.45);
}

.mechanics-card.func-card {
  border-color: rgba(168, 85, 247, 0.45);
}

.loop-strip {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-top: 4px;
}

.loop-item-box {
  background: var(--bg-input);
  border: 1px solid var(--border-highlight);
  border-radius: 6px;
  padding: 5px 9px;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 42px;
  font-family: var(--font-mono);
}

.loop-item-box.past-item {
  opacity: 0.5;
  border-color: #1e293b;
}

.loop-item-box.current-item {
  background: rgba(6, 182, 212, 0.2);
  border: 1.5px solid var(--accent-secondary);
  box-shadow: 0 0 10px rgba(6, 182, 212, 0.25);
}

.loop-item-ptr {
  font-size: 9px;
  color: #22d3ee;
  font-weight: 700;
}

.loop-item-val {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--text-primary);
}

/* Condition Evaluator Grid */
.cond-eval-grid {
  display: grid;
  grid-template-columns: 1fr auto 1fr auto;
  align-items: center;
  gap: 8px;
  background: var(--bg-input);
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  font-family: var(--font-mono);
  font-size: 12px;
}

.cond-operand {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.cond-expr-label {
  font-size: 10px;
  color: var(--text-muted);
}

.cond-expr-val {
  font-weight: 700;
  color: #e2e8f0;
}

.cond-op-badge {
  padding: 2px 7px;
  border-radius: 4px;
  background: rgba(245, 158, 11, 0.18);
  color: #fbbf24;
  font-weight: 700;
}

.cond-verdict {
  padding: 4px 10px;
  border-radius: 6px;
  font-weight: 800;
  font-size: 12px;
}

.cond-verdict.verdict-true {
  background: var(--accent-success-bg);
  color: #34d399;
  border: 1px solid var(--accent-success);
}

.cond-verdict.verdict-false {
  background: var(--accent-danger-bg);
  color: #f87171;
