class RuleBasedExplainer {
  enrichTraceWithExplanations(traceResult) {
    if (!traceResult || !traceResult.steps) return traceResult;
    const steps = traceResult.steps;

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      const prevStep = i > 0 ? steps[i - 1] : null;
      const nextStep = i + 1 < steps.length ? steps[i + 1] : null;
      step.explanations = this.buildStepExplanation(step, prevStep, nextStep);
      step.practiceQuestion = this.buildPracticeChallenge(step, nextStep);
    }

    traceResult.executionSummary = this.buildExecutionSummary(traceResult);
    return traceResult;
  }

  buildStepExplanation(step, prevStep, nextStep) {
    const code = step.codeText || "";
    const op = step.operationDetail || {};
    const cond = step.condition;
    const beforeVars = step.beforeVars || {};

    let whatBeginner = "";
    let whatTechnical = "";

    // 1. What the current line does (Beginner & Technical)
    if (step.eventType === "CLASS_DEF") {
      whatBeginner = `Creates a class named \`${op.className}\`. Think of a class as a container that holds methods (functions). Creating the class does not run the method code yet.`;
      whatTechnical = `Executes \`class ${op.className}:\` definition in \`${step.functionName}\`, allocating the class namespace before method registration.`;
    } else if (step.eventType === "METHOD_DEF" || step.eventType === "FUNC_DEF") {
      whatBeginner = `Defines the method \`${op.funcName}(${(op.params || []).join(", ")})\`. Python records where this method is located, and waits until the method is called to run the lines inside it.`;
      whatTechnical = `Registers function/method object \`${op.funcName}\` with formal parameters \`(${(op.params || []).join(", ")})\`. The body is not executed at definition time.`;
    } else if (step.eventType === "FUNC_CALL") {
      const bindingsStr = (op.paramBindings || [])
        .map((b) => `\`${b.param} = ${b.val}\``)
        .join(", ");
      whatBeginner = `Calls \`${op.funcName}()\` and passes the input into its parameter: ${bindingsStr}. Now Python enters the method body and starts running its lines one by one!`;
      whatTechnical = `Invokes \`${op.funcName}\`, pushing a new stack frame \`${step.functionName}\` and binding argument values to local parameters (${bindingsStr}).`;
    } else if (step.eventType === "LOOP_ITER" && op.kind === "for_iter") {
      const extraIdx = op.indexedElementInfo
        ? ` At this index, \`${op.indexedElementInfo.arrayName}[${op.indexedElementInfo.indexVal}]\` is \`${op.indexedElementInfo.elementVal}\`.`
        : "";
      whatBeginner = `Starts **loop iteration ${op.iteration} of ${op.total}**: Python sets the loop variable \`${op.iterVar} = ${op.iterVal}\`.${extraIdx}`;
      whatTechnical = `\`for\` loop iterator advances to pass ${op.iteration}/${op.total}, binding \`${op.iterVar} = ${op.iterVal}\` in local scope.${extraIdx}`;
    } else if (step.eventType === "LOOP_END") {
      whatBeginner = `The loop has finished checking every item in the sequence. Python now exits the loop and moves to the line after the loop.`;
      whatTechnical = `Loop iterator exhausted after ${op.total || "all"} iterations; control transfers past the loop suite.`;
    } else if (step.eventType === "AUG_ASSIGN") {
      const resetContext =
        op.target === "c"
          ? ` (\`c\` tracks the current candidate subarray sum; adding \`${op.rhsExpr}\` updates our running candidate sum from \`${op.beforeVal}\` to \`${op.afterVal}\`.)`
          : "";
      whatBeginner = `Python adds \`${op.rhsExpr}\` (\`${op.rhsVal}\`) to \`${op.target}\` (which was \`${op.beforeVal}\`): \`${op.beforeVal} ${op.baseOp} (${op.rhsVal}) = ${op.afterVal}\`, and stores \`${op.afterVal}\` back in \`${op.target}\`.${resetContext}`;
      whatTechnical = `Augmented assignment \`${code}\` evaluates \`${op.target} ${op.baseOp} ${op.rhsExpr}\` (\`${op.beforeVal} ${op.baseOp} ${op.rhsVal} -> ${op.afterVal}\`) and updates \`${op.target}\` in place.`;
    } else if (step.eventType === "ASSIGN") {
      let specialNote = "";
      if (op.target === "c" && op.afterVal === "0" && !op.isCreated) {
        specialNote = ` Resetting \`c = 0\` discards the negative candidate sum so it won't reduce the sum of future subarrays.`;
      } else if (op.target === "c" && op.isCreated) {
        specialNote = ` \`c\` will track our current candidate contiguous subarray sum.`;
      } else if (op.target === "ans" && op.isCreated) {
        specialNote = ` \`ans\` tracks the best subarray sum found so far. Initializing \`ans = nums[0]\` (${op.afterVal}) ensures the code works even if every number in \`nums\` is negative!`;
      } else if (op.target === "ans" && !op.isCreated) {
        specialNote = ` Because our current sum \`c\` (${op.afterVal}) beat or tied the previous best \`ans\` (${op.beforeVal}), \`ans\` is updated to \`${op.afterVal}\`!`;
      }
      whatBeginner = op.isCreated
        ? `A variable named \`${op.target}\` is created and assigned the value \`${op.afterVal}\`.${specialNote}`
        : `Variable \`${op.target}\` is updated from \`${op.beforeVal}\` to \`${op.afterVal}\` (from \`${op.rhsExpr}\`).${specialNote}`;
      whatTechnical = `Assignment \`${code}\` evaluates RHS \`${op.rhsExpr}\` to \`${op.afterVal}\` and ${op.isCreated ? "initializes" : "rebinds"} local identifier \`${op.target}\`.${specialNote}`;
    } else if (step.eventType === "CONDITION" && cond) {
      const outcomeStr = cond.result ? "True" : "False";
      let kadaneNote = "";
      if (cond.expr === "c >= ans") {
        kadaneNote = cond.result
          ? ` Since candidate sum \`c\` (${cond.leftVal}) is at least as large as our best sum \`ans\` (${cond.rightVal}), Python will enter the \`if\` block to update \`ans\`!`
          : ` Since candidate sum \`c\` (${cond.leftVal}) is smaller than our best sum \`ans\` (${cond.rightVal}), \`ans\` stays unchanged and Python skips the \`if\` block.`;
      } else if (cond.expr === "c < 0") {
        kadaneNote = cond.result
          ? ` Since \`c\` (${cond.leftVal}) is negative, keeping it would only hurt future subarray sums—so Python enters the \`if\` block to reset \`c = 0\`.`
          : ` Since \`c\` (${cond.leftVal}) is not negative, we keep accumulating \`c\` and skip the reset block.`;
      }
      whatBeginner = `Compares \`${cond.expr}\` using current values: \`${cond.leftVal} ${cond.operator} ${cond.rightVal}\` evaluates to **${outcomeStr}**.${kadaneNote}`;
      whatTechnical = `Evaluates relational predicate \`${cond.expr}\` with operands \`${cond.leftExpr}=${cond.leftVal}\` and \`${cond.rightExpr}=${cond.rightVal}\`, yielding boolean \`${outcomeStr}\`.`;
    } else if (step.eventType === "RETURN") {
      whatBeginner = `The function sends the current value of \`${op.expr}\` (\`${op.returnVal}\`) back to the code that called the function and finishes execution!`;
      whatTechnical = `\`return ${op.expr}\` unwinds activation frame \`${step.functionName}\` and returns value \`${op.returnVal}\` to the caller.`;
    } else if (step.eventType === "PRINT") {
      whatBeginner = `Prints \`"${op.output}"\` to the console output panel.`;
      whatTechnical = `Writes formatted evaluation string \`"${op.output}"\` to standard output (\`stdout\`).`;
    } else if (step.eventType === "BREAK") {
      whatBeginner = `\`break\` immediately stops the current loop and jumps past the loop body.`;
      whatTechnical = `Executes \`break\`, terminating the innermost enclosing loop suite.`;
    } else if (step.eventType === "CONTINUE") {
      whatBeginner = `\`continue\` skips the rest of the current loop pass and jumps straight to the next iteration.`;
      whatTechnical = `Executes \`continue\`, transferring control to the loop header for the next iteration.`;
    } else if (step.eventType === "EXCEPTION") {
      whatBeginner = `Execution stopped because of an error on this line: \`${op.message}\`.`;
      whatTechnical = `Unhandled runtime exception raised: \`${op.message}\`.`;
    } else {
      whatBeginner = `Executes \`${code}\` on Line ${step.line}.`;
      whatTechnical = `Executes statement \`${code}\` at line ${step.line} in scope \`${step.functionName}\`.`;
    }

    // 2. What the important symbols mean
    const symbolsMeaning = this.explainSymbolsInLine(code);

    // 3. Why this line is executing
    const whyExecuting = this.explainWhyLineExecutes(step, prevStep);

    // 4. What the variables contain before execution
    const beforeKeys = Object.keys(beforeVars);
    const variablesBefore =
      beforeKeys.length === 0
        ? "No local variables existed in this scope before this line ran."
        : beforeKeys.map((k) => `\`${k} = ${beforeVars[k]}\``).join(", ");

    // 5. What changes after execution
    const whatChangesAfter = step.changedSummary || "No variable values changed.";

    // 6. Why a condition is True or False
    let whyCondition = "This line is not a conditional check (`if` / `elif` / `while`).";
    if (cond) {
      if (step.eventType === "LOOP_ITER" && op.kind === "for_iter") {
        whyCondition = `True because index pass ${op.iteration} is within the sequence length (${op.total}), assigning \`${op.iterVar} = ${op.iterVal}\`.`;
      } else if (step.eventType === "LOOP_END") {
        whyCondition = `False because all ${op.total || ""} items in the sequence have been processed.`;
      } else {
        whyCondition = `\`${cond.expr}\` substituted \`${cond.leftExpr} = ${cond.leftVal}\` and \`${cond.rightExpr} = ${cond.rightVal}\`. Comparing \`${cond.leftVal} ${cond.operator} ${cond.rightVal}\` is **${cond.result ? "True" : "False"}**.`;
      }
    }

    // 7. Which line executes next and why
    const whatNext = this.explainWhatHappensNext(step, nextStep);

    return {
      whatBeginner,
      whatTechnical,
      symbolsMeaning,
      whyExecuting,
      variablesBefore,
      whatChangesAfter,
      whyCondition,
      whatNext
    };
  }

  explainSymbolsInLine(codeText) {
    const matches = [];
    for (const item of PYTHON_SYMBOLS_LIBRARY) {
      if (codeText.includes(item.token)) {
        matches.push(`• \`${item.label}\`: ${item.desc}`);
      }
    }
    if (matches.length === 0) {
      return "• Standard Python variable or expression evaluation.";
    }
    return matches.slice(0, 3).join("<br>");
  }

  explainWhyLineExecutes(step, prevStep) {
    if (!prevStep) {
      return `Line ${step.line} executes first because Python reads the file from top to bottom starting at the first statement.`;
    }
    if (step.eventType === "FUNC_CALL") {
      return `The class and method definitions finished registering, and the runner invoked \`${step.operationDetail.funcName}(nums)\` with the current input.`;
    }
    if (prevStep.eventType === "FUNC_CALL") {
      return `Because \`${prevStep.functionName}\` was just called, Python jumped to the first line inside its body (Line ${step.line}).`;
    }
    if (prevStep.eventType === "CONDITION" && prevStep.condition) {
      if (prevStep.condition.result) {
        return `Because the condition \`${prevStep.condition.expr}\` on Line ${prevStep.line} was **True**, Python stepped inside the indented \`if\` block to run Line ${step.line}.`;
      }
      return `Because the condition \`${prevStep.condition.expr}\` on Line ${prevStep.line} was **False**, Python skipped the indented block and moved to Line ${step.line}.`;
    }
    if (prevStep.eventType === "LOOP_ITER") {
      return `Because the loop on Line ${prevStep.line} started iteration #${prevStep.loop ? prevStep.loop.currentIteration : 1}, Python entered the indented loop body at Line ${step.line}.`;
    }
    if (prevStep.eventType === "LOOP_END") {
      return `Because the loop on Line ${prevStep.line} finished all iterations, Python exited the loop and moved to Line ${step.line}.`;
    }
    if (step.line < prevStep.line) {
      return `Line ${prevStep.line} completed the current pass of the loop body, so Python jumped **back up** to the loop header on Line ${step.line} for the next iteration.`;
    }
    return `Sequential execution: after completing Line ${prevStep.line}, Python moved down to the next statement on Line ${step.line}.`;
  }

  explainWhatHappensNext(step, nextStep) {
    if (!nextStep) {
      return `Program execution is complete! No more lines remain.`;
    }
    if (step.eventType === "CONDITION" && step.condition) {
      return step.condition.result
        ? `Because the condition is **True**, Python will enter the indented block at **Line ${nextStep.line}** (\`${nextStep.codeText}\`).`
        : `Because the condition is **False**, Python skips the indented block and jumps to **Line ${nextStep.line}** (\`${nextStep.codeText}\`).`;
    }
    if (step.eventType === "LOOP_ITER") {
      return `Python enters the loop body at **Line ${nextStep.line}** (\`${nextStep.codeText}\`).`;
    }
    if (step.eventType === "LOOP_END") {
      return `Python exits the loop and jumps to **Line ${nextStep.line}** (\`${nextStep.codeText}\`).`;
    }
    if (nextStep.line < step.line) {
      return `Having reached the end of the loop pass, Python jumps back up to the loop header on **Line ${nextStep.line}** (\`${nextStep.codeText}\`).`;
    }
    return `Execution moves to **Line ${nextStep.line}** (\`${nextStep.codeText}\`).`;
  }

  buildPracticeChallenge(step, nextStep) {
    if (!nextStep) return null;
    if (nextStep.eventType === "CONDITION" && nextStep.condition) {
      const c = nextStep.condition;
      return {
        prompt: `Practice Prediction: On the next step (Line ${nextStep.line}: \`${nextStep.codeText}\`), what will \`${c.expr}\` evaluate to?`,
        options: [
          { label: `True (${c.leftVal} ${c.operator} ${c.rightVal} is True)`, correct: c.result === true },
          { label: `False (${c.leftVal} ${c.operator} ${c.rightVal} is False)`, correct: c.result === false }
        ],
        explanation: `With \`${c.leftExpr} = ${c.leftVal}\` and \`${c.rightExpr} = ${c.rightVal}\`, \`${c.leftVal} ${c.operator} ${c.rightVal}\` evaluates to **${c.result ? "True" : "False"}**.`
      };
    }
    if (
      (nextStep.eventType === "ASSIGN" || nextStep.eventType === "AUG_ASSIGN") &&
      nextStep.changedVars &&
      nextStep.changedVars.length > 0
    ) {
      const targetName = nextStep.changedVars[0].name;
      const row = nextStep.variables.find((v) => v.name === targetName);
      if (row) {
        const actual = row.current;
        const numVal = Number(actual);
        const opt1 = !Number.isNaN(numVal) ? String(numVal + 2) : `"None"`;
        const opt2 = !Number.isNaN(numVal) ? String(numVal - 1) : `0`;
        const options = [
          { label: `${targetName} = ${actual}`, correct: true },
          { label: `${targetName} = ${opt1}`, correct: false },
          { label: `${targetName} = ${opt2}`, correct: false }
        ].sort(() => Math.random() - 0.5);
        return {
          prompt: `Practice Prediction: After Line ${nextStep.line} (\`${nextStep.codeText}\`) executes, what will \`${targetName}\` be?`,
          options,
          explanation: `Line ${nextStep.line} sets \`${nextStep.changedSummary}\`.`
        };
      }
    }
    return null;
  }

  buildExecutionSummary(traceResult) {
    if (!traceResult.ok || !traceResult.steps.length) {
      return `Execution stopped before completion: ${traceResult.errorMessage || "Check syntax or input."}`;
    }
    const steps = traceResult.steps;
    const lastStep = steps[steps.length - 1];
    const totalSteps = steps.length;
    const ansUpdates = steps.filter(
      (s) =>
        (s.eventType === "ASSIGN" || s.eventType === "AUG_ASSIGN") &&
        s.changedVars &&
        s.changedVars.some((c) => c.name === "ans")
    );
    const resets = steps.filter(
      (s) =>
        s.eventType === "ASSIGN" &&
        s.operationDetail &&
        s.operationDetail.target === "c" &&
        s.operationDetail.afterVal === "0" &&
        !s.operationDetail.isCreated
    );

    if (traceResult.finalResult !== null) {
      return `Completed in **${totalSteps} steps**. Final returned value: **\`${traceResult.finalResult}\`**. During execution, best answer \`ans\` was initialized/updated **${ansUpdates.length} time(s)**, and candidate sum \`c\` was reset to \`0\` **${resets.length} time(s)** when it became negative.`;
    }
    if (lastStep.stdout && lastStep.stdout.length > 0) {
      return `Completed in **${totalSteps} steps**. Console output: \`${lastStep.stdout.join(" | ")}\`.`;
    }
    return `Completed in **${totalSteps} steps**.`;
  }

  answerBuiltInQuestion(questionId, step, traceResult) {
    if (!step) {
      return "Run or analyze the code first to inspect a step.";
    }
    const exp = step.explanations;
    const cond = step.condition;
    const op = step.operationDetail || {};

    switch (questionId) {
      case "what_line_does":
        return `**What Line ${step.line} (\`${step.codeText}\`) does:** ${exp.whatBeginner}`;

      case "why_var_changed":
        if (!step.changedVars || step.changedVars.length === 0) {
          return `**Why no variable changed on Step ${step.stepIndex}:** Line ${step.line} (\`${step.codeText}\`) is a \`${step.eventType}\` step, which checks control flow or definitions without modifying variable values.`;
        }
        return `**Why variable changed on Step ${step.stepIndex}:** ${exp.whatChangesAfter}. ${exp.whatBeginner}`;

      case "why_cond_true":
        if (!cond) {
          return `Line ${step.line} (\`${step.codeText}\`) does not evaluate a True/False condition. Step to an \`if\`, \`elif\`, \`for\`, or \`while\` line to inspect a condition.`;
        }
        if (!cond.result) {
          return `On Step ${step.stepIndex}, the condition \`${cond.expr}\` actually evaluated to **False** (not True), because \`${cond.leftVal} ${cond.operator} ${cond.rightVal}\` is False.`;
        }
        return `**Why \`${cond.expr}\` is True on Step ${step.stepIndex}:** ${exp.whyCondition}`;

      case "why_cond_false":
        if (!cond) {
          return `Line ${step.line} (\`${step.codeText}\`) does not evaluate a True/False condition. Step to an \`if\`, \`elif\`, \`for\`, or \`while\` line to inspect a condition.`;
        }
        if (cond.result) {
          return `On Step ${step.stepIndex}, the condition \`${cond.expr}\` actually evaluated to **True** (not False), because \`${cond.leftVal} ${cond.operator} ${cond.rightVal}\` is True.`;
        }
        return `**Why \`${cond.expr}\` is False on Step ${step.stepIndex}:** ${exp.whyCondition}`;

      case "what_happens_next":
        return `**What happens next:** ${exp.whatNext}`;

      case "why_loop_repeat":
        if (!step.loop) {
          return `Execution is not currently inside a loop on Step ${step.stepIndex}.`;
        }
        if (step.loop.isFinished) {
          return `**Why the loop stopped:** All ${step.loop.totalIterations} items in \`${step.loop.iterExpr}\` have been visited, so the loop exits.`;
        }
        return `**Why the loop repeated (Iteration ${step.loop.currentIteration}${step.loop.totalIterations ? " of " + step.loop.totalIterations : ""}):** The loop continues as long as there are remaining items in \`${step.loop.iterExpr || step.loop.condition}\`. Currently \`${step.loop.iterVar || "condition"} = ${step.loop.currentItemValue || "True"}\`.`;

      case "why_return_value": {
        const retStep =
          step.eventType === "RETURN"
            ? step
            : [...traceResult.steps].reverse().find((s) => s.eventType === "RETURN");
        if (!retStep) {
          return `This program does not execute a \`return\` statement.`;
        }
        return `**Why the function returns \`${retStep.returnValue}\` (on Step ${retStep.stepIndex}, Line ${retStep.line}):** At the end of the function, \`${retStep.operationDetail.expr}\` holds \`${retStep.returnValue}\`, which is the best maximum subarray sum accumulated across all loop iterations.`;
      }

      case "what_if_change_input":
        return `**What happens if you change the input?** Use the **Input Playground** bar above! For example, try \`nums = [-5, -2, -8]\` (all negative numbers) to see why initializing \`ans = nums[0]\` returns \`-2\`, or try \`nums = [1, 2, 3, 4]\` to see \`c\` accumulate to \`10\` without ever resetting to \`0\`.`;

      case "what_symbol_means":
        return `**Symbols on Line ${step.line} (\`${step.codeText}\`):**<br>${exp.symbolsMeaning}`;

      default:
        return "This question is outside the built-in rule-based explanation library.";
    }
  }

  explainVariableClick(varName, step, traceResult) {
    const history = [];
    traceResult.steps.forEach((s) => {
      const v = (s.variables || []).find((row) => row.name === varName);
      if (v && (v.status === "created" || v.status === "updated")) {
        history.push(`Step ${s.stepIndex} (L${s.line}): \`${v.previous}\` → \`${v.current}\``);
      }
    });

    const curRow = (step.variables || []).find((r) => r.name === varName);
    const curVal = curRow ? curRow.current : "not in scope";
    const roleMap = {
      nums: "The input list of numbers passed into the method.",
      c: "Tracks the current candidate contiguous subarray sum. Resets to `0` whenever it drops below `0`.",
      ans: "Tracks the maximum subarray sum seen so far across all iterations.",
      i: "Loop index variable stepping from `0` to `len(nums) - 1`."
    };
    const role = roleMap[varName] || `Variable of type \`${curRow ? curRow.type : "unknown"}\` in \`${step.functionName}\`.`;

    return `**Variable \`${varName}\` (Current value: \`${curVal}\`):** ${role}<br>**Change History:** ${history.length ? history.join(" | ") : "No changes recorded."}`;
  }
}

window.RuleBasedExplainer = RuleBasedExplainer;

/* Input Playground Bar (Section 11) */
.input-playground-bar {
  height: 40px;
  background-color: var(--bg-elevated);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  gap: 12px;
  flex-shrink: 0;
}

.playground-left,
.playground-presets {
  display: flex;
  align-items: center;
  gap: 6px;
}

.playground-label {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-secondary);
  white-space: nowrap;
}

.playground-input {
  width: 290px;
  background: var(--bg-input);
  color: var(--accent-cyan);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 4px 8px;
  font-family: var(--font-mono);
  font-size: 12px;
  outline: none;
}

.playground-input:focus {
  border-color: var(--accent-blue);
}

.btn-chip {
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--bg-panel);
  color: var(--text-secondary);
  font-size: 11px;
  font-family: var(--font-mono);
  cursor: pointer;
}

.btn-chip:hover {
  color: var(--text-primary);
  border-color: var(--accent-blue);
}

/* Validation Banner */
.validation-banner {
  background: rgba(248, 81, 73, 0.15);
  border-bottom: 1px solid var(--accent-red);
  color: #ffa198;
  padding: 8px 12px;
  font-size: 12px;
  font-family: var(--font-mono);
}

/* Algorithm Purpose Banner */
.purpose-banner {
  background: rgba(88, 166, 255, 0.08);
  border: 1px solid rgba(88, 166, 255, 0.25);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  font-size: 12px;
  line-height: 1.45;
  color: var(--text-primary);
}

.purpose-banner code {
  font-family: var(--font-mono);
  color: var(--accent-cyan);
  background: var(--bg-elevated);
  padding: 1px 4px;
  border-radius: 3px;
}

/* Practice Mode Card */
.practice-card {
  background: rgba(188, 140, 255, 0.1);
  border: 1px solid rgba(188, 140, 255, 0.4);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.practice-options {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.practice-opt-btn {
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--bg-input);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 12px;
  cursor: pointer;
}

.practice-opt-btn.correct {
  border-color: var(--accent-green);
  background: rgba(63, 185, 80, 0.2);
  color: #7ee787;
}

.practice-opt-btn.wrong {
  border-color: var(--accent-red);
  background: rgba(248, 81, 73, 0.2);
  color: #ffa198;
}

/* Visual List Array Strip */
.list-strip-card {
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.list-cells-row {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.list-cell {
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: 4px;
  min-width: 34px;
  padding: 3px 5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  font-family: var(--font-mono);
}

.list-cell.active-idx {
  border-color: var(--accent-amber);
  background: rgba(210, 153, 34, 0.2);
}

.list-cell-i {
  font-size: 9.5px;
  color: var(--text-muted);
}

.list-cell-v {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

/* Variable History Box */
.var-history-box {
  background: var(--bg-input);
  border: 1px solid var(--accent-cyan);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  font-size: 12px;
  line-height: 1.5;
}

/* Built-In Code Questions Section */
.questions-section {
  margin-top: auto;
  border-top: 1px solid var(--border-subtle);
  padding-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.question-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.q-chip {
  padding: 4px 8px;
  font-size: 11px;
  border-radius: var(--radius-sm);
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  cursor: pointer;
}

.q-chip:hover,
.q-chip.active {
  color: var(--text-primary);
  border-color: var(--accent-blue);
  background: rgba(88, 166, 255, 0.14);
}

.question-answer-box {
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-primary);
  min-height: 54px;
}

.question-answer-box code {
  font-family: var(--font-mono);
  color: var(--accent-cyan);
}

/* 7-Card Beginner Explanation Grid */
.explanation-cards-grid-7 {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  padding: 8px 12px;
  overflow-y: auto;
}

// app.js — Separated UI & Execution History Controller
// Synchronizes Panel A (Code Editor), Panel B (Execution Visualizer),
// Panel C (Variable Inspector & Built-In Questions), and Panel D (7-Part Beginner Explanation).

class CodeFlowVisualizerApp {
  constructor() {
    this.engine = new window.PythonExecutionEngine();
    this.explainer = new window.RuleBasedExplainer();

    this.currentPresetKey = "max_subarray";
    this.originalCode = window.PRELOADED_PROGRAMS[this.currentPresetKey].code;
    this.sourceCode = this.originalCode;
    this.inputCode = window.PRELOADED_PROGRAMS[this.currentPresetKey].defaultInput;
    this.algorithmOverview = window.PRELOADED_PROGRAMS[this.currentPresetKey].algorithmOverview;

    this.traceResult = null;
    this.currentStepIdx = 0;
    this.isPlaying = false;
    this.isPaused = false;
    this.playInterval = null;
    this.playSpeedMs = 950;
    this.explanationMode = "beginner"; // 'beginner' | 'technical'
    this.practiceMode = false;
    this.isEditing = false;
    this.activeQuestionId = "what_line_does";
    this.selectedHistoryVar = null;

    this.initDOM();
    this.bindEvents();
    this.loadPreset(this.currentPresetKey);
  }

  initDOM() {
    // Execution Controls (Section 5)
    this.btnStart = document.getElementById("btnStart");
    this.btnPause = document.getElementById("btnPause");
    this.btnResume = document.getElementById("btnResume");
    this.btnPrev = document.getElementById("btnPrev");
    this.btnNext = document.getElementById("btnNext");
    this.btnRestart = document.getElementById("btnRestart");
    this.stepBadge = document.getElementById("stepBadge");
    this.timelineSlider = document.getElementById("timelineSlider");
    this.speedSelect = document.getElementById("speedSelect");
    this.btnPracticeMode = document.getElementById("btnPracticeMode");

    // Input Playground (Section 11)
    this.inputPlaygroundField = document.getElementById("inputPlaygroundField");
    this.btnRunInput = document.getElementById("btnRunInput");
    this.inputPresetBtns = document.querySelectorAll(".btn-chip");

    // Panel A: Code Editor
    this.presetSelect = document.getElementById("presetSelect");
    this.btnLoadExample = document.getElementById("btnLoadExample");
    this.btnEditCode = document.getElementById("btnEditCode");
    this.btnReset = document.getElementById("btnReset");
    this.btnAnalyzeCode = document.getElementById("btnAnalyzeCode");
    this.validationBanner = document.getElementById("validationBanner");
    this.codeLinesContainer = document.getElementById("codeLinesContainer");
    this.liveEditorWrap = document.getElementById("liveEditorWrap");
    this.editorLineNumbers = document.getElementById("editorLineNumbers");
    this.codeTextarea = document.getElementById("codeTextarea");

    // Panel B: Execution Visualizer
    this.flowEventBadge = document.getElementById("flowEventBadge");
    this.algorithmPurposeBox = document.getElementById("algorithmPurposeBox");
    this.practiceCard = document.getElementById("practiceCard");
    this.practicePrompt = document.getElementById("practicePrompt");
    this.practiceOptions = document.getElementById("practiceOptions");
    this.practiceFeedback = document.getElementById("practiceFeedback");
    this.metricStep = document.getElementById("metricStep");
    this.metricCurrentLine = document.getElementById("metricCurrentLine");
    this.metricLoopIter = document.getElementById("metricLoopIter");
    this.metricNextLine = document.getElementById("metricNextLine");
    this.flowScopeLabel = document.getElementById("flowScopeLabel");
    this.flowCodeStatement = document.getElementById("flowCodeStatement");
    this.flowStepSummary = document.getElementById("flowStepSummary");
    this.flowBeforeAfter = document.getElementById("flowBeforeAfter");
    this.flowConditionResult = document.getElementById("flowConditionResult");
    this.executionSummaryTag = document.getElementById("executionSummaryTag");
    this.flowchartSvgWrap = document.getElementById("flowchartSvgWrap");

    // Panel C: Variable Inspector & Built-In Questions
    this.activeScopeBadge = document.getElementById("activeScopeBadge");
    this.varInspectorTbody = document.getElementById("varInspectorTbody");
    this.visualListsContainer = document.getElementById("visualListsContainer");
    this.varHistoryBox = document.getElementById("varHistoryBox");
    this.questionChips = document.querySelectorAll(".q-chip");
    this.questionAnswerBox = document.getElementById("questionAnswerBox");

    // Panel D: 7-Part Beginner Explanation
    this.modeBtns = document.querySelectorAll(".mode-btn");
    this.exp1WhatLineDoes = document.getElementById("exp1WhatLineDoes");
    this.exp2Symbols = document.getElementById("exp2Symbols");
    this.exp3WhyNow = document.getElementById("exp3WhyNow");
    this.exp4VarsBefore = document.getElementById("exp4VarsBefore");
    this.exp5ChangesAfter = document.getElementById("exp5ChangesAfter");
    this.exp6WhyCondition = document.getElementById("exp6WhyCondition");
    this.exp7NextLine = document.getElementById("exp7NextLine");

    // Populate Program Selector
    Object.entries(window.PRELOADED_PROGRAMS).forEach(([key, item]) => {
      const opt = document.createElement("option");
      opt.value = key;
      opt.textContent = item.title;
      this.presetSelect.appendChild(opt);
    });
  }

  bindEvents() {
    // Execution Controls (Section 5)
    this.btnStart.addEventListener("click", () => {
      this.currentStepIdx = 0;
      this.renderStep();
      this.startPlayback();
    });

    this.btnPause.addEventListener("click", () => {
      this.pausePlayback(true);
    });

    this.btnResume.addEventListener("click", () => {
      this.startPlayback();
    });

    this.btnPrev.addEventListener("click", () => {
      this.pausePlayback(false);
      this.goToStep(this.currentStepIdx - 1);
    });

    this.btnNext.addEventListener("click", () => {
      this.pausePlayback(false);
      this.goToStep(this.currentStepIdx + 1);
    });

    this.btnRestart.addEventListener("click", () => {
      this.pausePlayback(false);
      this.goToStep(0);
    });

    this.timelineSlider.addEventListener("input", (e) => {
      this.pausePlayback(false);
      this.goToStep(Number(e.target.value));
    });

    this.speedSelect.addEventListener("change", (e) => {
      this.playSpeedMs = Number(e.target.value);
      if (this.isPlaying) {
        this.pausePlayback(true);
        this.startPlayback();
      }
    });

    this.btnPracticeMode.addEventListener("click", () => {
      this.practiceMode = !this.practiceMode;
      this.btnPracticeMode.textContent = this.practiceMode
        ? "Practice Mode: ON"
        : "Practice Mode: OFF";
      this.btnPracticeMode.classList.toggle("btn-accent", this.practiceMode);
      this.renderStep();
    });

    // Input Playground (Section 11)
    this.btnRunInput.addEventListener("click", () => {
      this.inputCode = this.inputPlaygroundField.value;
      this.analyzeAndRun();
    });

    this.inputPlaygroundField.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        this.inputCode = this.inputPlaygroundField.value;
        this.analyzeAndRun();
      }
    });

    this.inputPresetBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        this.inputPlaygroundField.value = btn.dataset.input;
        this.inputCode = btn.dataset.input;
        this.analyzeAndRun();
      });
    });

    // Panel A: Code Editor Controls
    this.presetSelect.addEventListener("change", (e) => {
      this.loadPreset(e.target.value);
    });

    this.btnLoadExample.addEventListener("click", () => {
      this.loadPreset(this.presetSelect.value);
    });

    this.btnEditCode.addEventListener("click", () => {
      this.setEditMode(!this.isEditing);
    });

    this.btnReset.addEventListener("click", () => {
      this.pausePlayback(false);
      const prog = window.PRELOADED_PROGRAMS[this.currentPresetKey];
      this.sourceCode = prog.code;
      this.inputCode = prog.defaultInput;
      this.inputPlaygroundField.value = this.inputCode;
      this.codeTextarea.value = this.sourceCode;
      this.setEditMode(false);
      this.analyzeAndRun();
    });

    this.btnAnalyzeCode.addEventListener("click", () => {
      if (this.isEditing) {
        this.sourceCode = this.codeTextarea.value;
        this.setEditMode(false);
      }
      this.inputCode = this.inputPlaygroundField.value;
      this.analyzeAndRun();
    });

    this.codeTextarea.addEventListener("input", () => {
      this.updateEditorLineNumbers();
    });

    this.codeTextarea.addEventListener("scroll", () => {
      this.editorLineNumbers.scrollTop = this.codeTextarea.scrollTop;
    });

    // Built-In Code Questions (Section 9)
    this.questionChips.forEach((chip) => {
      chip.addEventListener("click", () => {
        this.questionChips.forEach((c) => c.classList.remove("active"));
        chip.classList.add("active");
        this.activeQuestionId = chip.dataset.qid;
        this.renderBuiltInQuestionAnswer();
      });
    });

    // Panel D: Explanation Mode Switcher
    this.modeBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        this.modeBtns.forEach((b) => b.classList.remove("active"));
        btn.classList.add("active");
        this.explanationMode = btn.dataset.mode;
        this.renderStep();
      });
    });

    // Keyboard shortcuts
    window.addEventListener("keydown", (e) => {
      if (
        document.activeElement === this.codeTextarea ||
        document.activeElement === this.inputPlaygroundField
      ) {
        return;
      }
      if (e.key === "ArrowRight") {
        e.preventDefault();
        this.pausePlayback(false);
        this.goToStep(this.currentStepIdx + 1);
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        this.pausePlayback(false);
        this.goToStep(this.currentStepIdx - 1);
      }
    });
  }

  loadPreset(key) {
    this.pausePlayback(false);
    this.currentPresetKey = key;
    const item = window.PRELOADED_PROGRAMS[key];
    this.originalCode = item.code;
    this.sourceCode = item.code;
    this.inputCode = item.defaultInput;
    this.algorithmOverview = item.algorithmOverview;

    this.inputPlaygroundField.value = this.inputCode;
    this.codeTextarea.value = this.sourceCode;
    this.selectedHistoryVar = null;
    this.varHistoryBox.classList.add("hidden");
    this.setEditMode(false);
    this.analyzeAndRun();
  }

  setEditMode(editing) {
    this.isEditing = editing;
    if (editing) {
      this.pausePlayback(false);
      this.codeTextarea.value = this.sourceCode;
      this.updateEditorLineNumbers();
      this.liveEditorWrap.classList.remove("hidden");
      this.codeLinesContainer.classList.add("hidden");
      this.btnEditCode.textContent = "Cancel Edit";
    } else {
      this.liveEditorWrap.classList.add("hidden");
      this.codeLinesContainer.classList.remove("hidden");
      this.btnEditCode.textContent = "Edit Code";
    }
  }

  updateEditorLineNumbers() {
    const count = this.codeTextarea.value.split("\n").length;
    const arr = [];
    for (let i = 1; i <= count; i++) arr.push(i);
    this.editorLineNumbers.innerHTML = arr.join("<br>");
  }

  analyzeAndRun() {
    this.pausePlayback(false);
    const rawTrace = this.engine.trace(this.sourceCode, this.inputCode);
    this.traceResult = this.explainer.enrichTraceWithExplanations(rawTrace);

    if (!this.traceResult.ok) {
      this.validationBanner.textContent = `⚠ ${this.traceResult.errorMessage}`;
      this.validationBanner.classList.remove("hidden");
    } else {
      this.validationBanner.classList.add("hidden");
    }

    const total = this.traceResult.steps.length;
    this.timelineSlider.max = Math.max(0, total - 1);
    this.currentStepIdx = 0;

    this.algorithmPurposeBox.innerHTML = `<strong>Algorithm Purpose:</strong> ${this.formatMarkdown(this.algorithmOverview)}`;
    this.executionSummaryTag.innerHTML = this.formatMarkdown(this.traceResult.executionSummary || "");

    this.renderStep();
  }

  goToStep(idx) {
    if (!this.traceResult || !this.traceResult.steps.length) return;
    this.currentStepIdx = Math.max(0, Math.min(idx, this.traceResult.steps.length - 1));
    this.renderStep();
  }

  startPlayback() {
    if (!this.traceResult || !this.traceResult.steps.length) return;
    if (this.currentStepIdx >= this.traceResult.steps.length - 1) {
      this.currentStepIdx = 0;
    }
    this.isPlaying = true;
    this.isPaused = false;
    this.updateTransportButtons();

    this.playInterval = setInterval(() => {
      if (this.currentStepIdx < this.traceResult.steps.length - 1) {
        this.currentStepIdx++;
        this.renderStep();
      } else {
        this.pausePlayback(false);
      }
    }, this.playSpeedMs);
  }

  pausePlayback(canResume = false) {
    this.isPlaying = false;
    this.isPaused = canResume;
    if (this.playInterval) {
      clearInterval(this.playInterval);
      this.playInterval = null;
    }
    this.updateTransportButtons();
  }

  updateTransportButtons() {
    const total = this.traceResult && this.traceResult.steps ? this.traceResult.steps.length : 0;
    this.btnStart.disabled = this.isPlaying || total === 0;
    this.btnPause.disabled = !this.isPlaying;
    this.btnResume.disabled = this.isPlaying || !this.isPaused || this.currentStepIdx >= total - 1;
    this.btnPrev.disabled = this.currentStepIdx <= 0 || total === 0;
    this.btnNext.disabled = this.currentStepIdx >= total - 1 || total === 0;
    this.btnRestart.disabled = total === 0;
  }

  renderStep() {
    if (!this.traceResult || !this.traceResult.steps.length) {
      this.codeLinesContainer.innerHTML = "";
      this.traceResult.rawLines.forEach((rawLine, idx) => {
        const lineNum = idx + 1;
        const isErrLine = this.traceResult.errorLine === lineNum;
        const row = document.createElement("div");
        row.className = "code-row";
        if (isErrLine) row.style.background = "rgba(248, 81, 73, 0.2)";
        row.innerHTML = `
          <div class="code-gutter"><span class="gutter-ln">${lineNum}</span></div>
          <div class="code-syntax">${this.highlightPythonSyntax(rawLine)}</div>
        `;
        this.codeLinesContainer.appendChild(row);
      });
      this.updateTransportButtons();
      return;
    }

    const steps = this.traceResult.steps;
    const step = steps[this.currentStepIdx];
    const total = steps.length;

    this.timelineSlider.value = this.currentStepIdx;
    this.stepBadge.textContent = `Step ${this.currentStepIdx + 1} / ${total}`;
    this.updateTransportButtons();

    this.renderPanelACodeEditor(step);
    this.renderPanelBVisualizer(step, total);
    this.renderPanelCVariableInspector(step);
    this.renderPanelDExplanation(step);
    this.renderBuiltInQuestionAnswer();
  }

  /* ==========================================
     PANEL A: Code Editor & Line States
     ========================================== */
  renderPanelACodeEditor(step) {
    const executedLinesMap = {};
    for (let i = 0; i < this.currentStepIdx; i++) {
      const s = this.traceResult.steps[i];
      if (!executedLinesMap[s.line]) executedLinesMap[s.line] = [];
      executedLinesMap[s.line].push(s.stepIndex);
    }

    this.codeLinesContainer.innerHTML = "";
    this.traceResult.rawLines.forEach((rawLine, idx) => {
      const lineNum = idx + 1;
      const isCurrent = step.line === lineNum;
      const isNext = step.nextLine === lineNum && !isCurrent;
      const wasExecuted = Boolean(executedLinesMap[lineNum]);

      const row = document.createElement("div");
      row.className = "code-row";
      if (isCurrent) row.classList.add("state-current");
      else if (isNext) row.classList.add("state-next");
      else if (wasExecuted) row.classList.add("state-executed");
      else row.classList.add("state-upcoming");

      const marker = isCurrent ? "▶" : isNext ? "↳" : wasExecuted ? "✓" : "";
      const markerColor = isCurrent ? "#58a6ff" : isNext ? "#d29922" : "#3fb950";

      let badgesHTML = "";
      if (isCurrent) {
        badgesHTML += `<span class="inline-state-tag">${this.escapeHTML(step.changedSummary)}</span>`;
      } else if (wasExecuted) {
        const recent = executedLinesMap[lineNum].slice(-2).map((n) => `#${n}`).join(",");
        badgesHTML += `<span class="step-order-tag">${recent}</span>`;
      }

      row.innerHTML = `
        <div class="code-gutter">
          <span class="gutter-marker" style="color:${markerColor}">${marker}</span>
          <span class="gutter-ln">${lineNum}</span>
        </div>
        <div class="code-syntax">${this.highlightPythonSyntax(rawLine)}</div>
        <div class="code-row-badges">${badgesHTML}</div>
      `;

      row.addEventListener("click", () => {
        const targetIdx = this.traceResult.steps.findIndex((s) => s.line === lineNum);
        if (targetIdx !== -1) {
          this.pausePlayback(false);
          this.goToStep(targetIdx);
        }
      });

      this.codeLinesContainer.appendChild(row);
    });
  }

  highlightPythonSyntax(line) {
    if (!line) return " ";
    let commentPart = "";
    let codePart = line;
    const hashIdx = line.indexOf("#");
    if (hashIdx !== -1) {
      codePart = line.slice(0, hashIdx);
      commentPart = `<span class="syn-com">${this.escapeHTML(line.slice(hashIdx))}</span>`;
    }

    const tokenRegex = /(".*?"|'.*?'|\b(?:class|def|return|if|elif|else|for|while|in|break|continue|and|or|not|True|False|None|self)\b|\b(?:print|range|len|min|max|abs|sum|list|int)\b|\b\d+(?:\.\d+)?\b)/g;
    const highlighted = this.escapeHTML(codePart).replace(tokenRegex, (match) => {
      if (match.startsWith('"') || match.startsWith("'")) {
        return `<span class="syn-str">${match}</span>`;
      }
      if (/^(class|def|return|if|elif|else|for|while|in|break|continue|and|or|not|True|False|None|self)$/.test(match)) {
        return `<span class="syn-kw">${match}</span>`;
      }
      if (/^(print|range|len|min|max|abs|sum|list|int)$/.test(match)) {
        return `<span class="syn-bi">${match}</span>`;
      }
      if (/^\d/.test(match)) {
        return `<span class="syn-num">${match}</span>`;
      }
      return match;
    });

    return highlighted + commentPart;
  }

  /* ==========================================
     PANEL B: Execution Visualizer (Center)
     ========================================== */
  renderPanelBVisualizer(step, total) {
    this.flowEventBadge.textContent = step.eventType;
    this.metricStep.textContent = `Step ${step.stepIndex} of ${total}`;
    this.metricCurrentLine.textContent = `Line ${step.line}`;
    this.metricNextLine.textContent = step.nextLine ? `Line ${step.nextLine}` : "Program End";

    if (step.loop) {
      const lp = step.loop;
      const iterStr = lp.totalIterations
        ? `Pass ${lp.currentIteration}/${lp.totalIterations} (${lp.iterVar}=${lp.currentItemValue ?? "done"})`
        : `Iteration #${lp.currentIteration}`;
      this.metricLoopIter.textContent = iterStr;
    } else {
      this.metricLoopIter.textContent = "None";
    }

    this.flowScopeLabel.textContent = step.functionName;
    this.flowCodeStatement.innerHTML = this.highlightPythonSyntax(step.codeText);

    const exp = step.explanations;
    const mainSummary =
      this.explanationMode === "technical" ? exp.whatTechnical : exp.whatBeginner;
    this.flowStepSummary.innerHTML = this.formatMarkdown(mainSummary);

    this.flowBeforeAfter.textContent = step.changedSummary;

    if (step.condition) {
      const c = step.condition;
      this.flowConditionResult.innerHTML = `<span style="color:${c.result ? "#3fb950" : "#f85149"}; font-weight:700;">${this.escapeHTML(c.leftVal)} ${this.escapeHTML(c.operator)} ${this.escapeHTML(c.rightVal)} → ${c.result ? "True" : "False"}</span>`;
    } else if (step.returnValue !== null) {
      this.flowConditionResult.innerHTML = `<span style="color:#3fb950; font-weight:700;">Returned: ${this.escapeHTML(step.returnValue)}</span>`;
    } else {
      this.flowConditionResult.textContent = "N/A (Not a condition step)";
    }

    // Practice Mode Prediction Card
    if (this.practiceMode && step.practiceQuestion) {
      const pq = step.practiceQuestion;
      this.practiceCard.classList.remove("hidden");
      this.practiceFeedback.classList.add("hidden");
      this.practicePrompt.innerHTML = this.formatMarkdown(pq.prompt);
      this.practiceOptions.innerHTML = "";
      pq.options.forEach((opt) => {
        const btn = document.createElement("button");
        btn.className = "practice-opt-btn";
        btn.textContent = opt.label;
        btn.addEventListener("click", () => {
          btn.classList.add(opt.correct ? "correct" : "wrong");
          this.practiceFeedback.innerHTML = `${opt.correct ? "✓ Correct! " : "✗ Not quite. "}${this.formatMarkdown(pq.explanation)}`;
          this.practiceFeedback.classList.remove("hidden");
        });
        this.practiceOptions.appendChild(btn);
      });
    } else {
      this.practiceCard.classList.add("hidden");
    }

    this.renderFlowchartSVG(step);
  }

  renderFlowchartSVG(step) {
    const cfg = this.traceResult.cfg;
    if (!cfg || !cfg.nodes.length) return;

    const nodeW = 195;
    const nodeH = 32;
    const vGap = 46;
    const svgW = 360;
    const svgH = Math.max(190, cfg.nodes.length * vGap + 26);

    const positions = {};
    cfg.nodes.forEach((n, idx) => {
      positions[n.id] = { x: svgW / 2, y: 22 + idx * vGap };
    });

    const activeId = `L${step.line}`;
    const nextId = step.nextLine ? `L${step.nextLine}` : "end";

    let edgesSVG = "";
    cfg.edges.forEach((edge) => {
      const p1 = positions[edge.from];
      const p2 = positions[edge.to];
      if (!p1 || !p2) return;

      const isActiveEdge = edge.from === activeId && edge.to === nextId;
      const stroke = isActiveEdge ? "#d29922" : edge.isBackEdge ? "#58a6ff" : "#30363d";
      const width = isActiveEdge ? 2.2 : 1.3;

      if (edge.isBackEdge || p2.y <= p1.y) {
        const leftX = 30;
        edgesSVG += `<path d="M ${p1.x - nodeW / 2} ${p1.y} C ${leftX} ${p1.y}, ${leftX} ${p2.y}, ${p2.x - nodeW / 2} ${p2.y}" fill="none" stroke="${stroke}" stroke-width="${width}" stroke-dasharray="4 2" />`;
      } else {
        edgesSVG += `<line x1="${p1.x}" y1="${p1.y + nodeH / 2}" x2="${p2.x}" y2="${p2.y - nodeH / 2}" stroke="${stroke}" stroke-width="${width}" />`;
      }
    });

    let nodesSVG = "";
    cfg.nodes.forEach((node) => {
      const pos = positions[node.id];
      const isCurrent = node.line === step.line;
      const isNext = node.line === step.nextLine && !isCurrent;

      let fill = "#161b22";
      let stroke = "#30363d";
      if (isCurrent) {
        fill = "rgba(88, 166, 255, 0.22)";
        stroke = "#58a6ff";
      } else if (isNext) {
        fill = "rgba(210, 153, 34, 0.14)";
        stroke = "#d29922";
      }

      if (node.type === "decision") {
        const pts = `${pos.x},${pos.y - nodeH / 2 - 2} ${pos.x + nodeW / 2 + 8},${pos.y} ${pos.x},${pos.y + nodeH / 2 + 2} ${pos.x - nodeW / 2 - 8},${pos.y}`;
        nodesSVG += `
          <g style="cursor:pointer" data-line="${node.line}">
            <polygon points="${pts}" fill="${fill}" stroke="${stroke}" stroke-width="${isCurrent ? 2 : 1.3}" />
            <text x="${pos.x}" y="${pos.y + 4}" text-anchor="middle" fill="#e6edf3" font-family="JetBrains Mono, monospace" font-size="10.5" font-weight="${isCurrent ? "700" : "500"}">
              ${this.escapeHTML(node.label)}
            </text>
          </g>
        `;
      } else {
        const rx = node.type === "start" || node.type === "end" || node.type === "loop" ? 15 : 5;
        nodesSVG += `
          <g transform="translate(${pos.x - nodeW / 2}, ${pos.y - nodeH / 2})" style="cursor:pointer" data-line="${node.line}">
            <rect width="${nodeW}" height="${nodeH}" rx="${rx}" fill="${fill}" stroke="${stroke}" stroke-width="${isCurrent ? 2 : 1.3}" />
            <text x="${nodeW / 2}" y="${nodeH / 2 + 4}" text-anchor="middle" fill="#e6edf3" font-family="JetBrains Mono, monospace" font-size="10.5" font-weight="${isCurrent ? "700" : "500"}">
              ${this.escapeHTML(node.label)}
            </text>
          </g>
        `;
      }
    });

    this.flowchartSvgWrap.innerHTML = `
      <svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}">
        ${edgesSVG}
        ${nodesSVG}
      </svg>
    `;

    this.flowchartSvgWrap.querySelectorAll("g[data-line]").forEach((g) => {
      g.addEventListener("click", () => {
        const ln = Number(g.dataset.line);
        const idx = this.traceResult.steps.findIndex((s) => s.line === ln);
        if (idx !== -1) {
          this.pausePlayback(false);
          this.goToStep(idx);
        }
      });
    });
  }

  /* ==========================================
     PANEL C: Variable Inspector & Questions
     ========================================== */
  renderPanelCVariableInspector(step) {
    this.activeScopeBadge.textContent = step.functionName;
    this.varInspectorTbody.innerHTML = "";
    this.visualListsContainer.innerHTML = "";

    const vars = step.variables || [];
    if (vars.length === 0) {
      this.varInspectorTbody.innerHTML = `
        <tr>
          <td colspan="5" style="text-align:center; color:var(--text-muted); padding:12px;">
            No local variables initialized in this scope yet.
          </td>
        </tr>
      `;
    } else {
      const iVar = vars.find((v) => v.name === "i" && typeof v.rawValue === "number");
      const currentIdx = iVar ? iVar.rawValue : null;

      vars.forEach((v) => {
        const tr = document.createElement("tr");
        tr.style.cursor = "pointer";
        if (v.status === "created") tr.classList.add("row-created");
        else if (v.status === "updated") tr.classList.add("row-updated");

        const statusClass =
          v.status === "created"
            ? "status-created"
            : v.status === "updated"
            ? "status-updated"
            : "status-unchanged";

        tr.innerHTML = `
          <td><strong>${this.escapeHTML(v.name)}</strong></td>
          <td class="val-prev">${this.escapeHTML(v.previous)}</td>
          <td class="val-curr">${this.escapeHTML(v.current)}</td>
          <td style="color:var(--text-secondary)">${v.type}</td>
          <td><span class="status-pill ${statusClass}">${v.status}</span></td>
        `;

        tr.addEventListener("click", () => {
          this.selectedHistoryVar = v.name;
          this.renderVariableHistory(v.name, step);
        });

        this.varInspectorTbody.appendChild(tr);

        // Render visual list cells if rawValue is an array
        if (Array.isArray(v.rawValue)) {
          const strip = document.createElement("div");
          strip.className = "list-strip-card";
          const cellsHTML = v.rawValue
            .map((itemVal, idx) => {
              const isPointed = currentIdx === idx;
              return `
                <div class="list-cell ${isPointed ? "active-idx" : ""}">
                  <span class="list-cell-i">${isPointed ? `i=${idx}▼` : `[${idx}]`}</span>
                  <span class="list-cell-v">${this.escapeHTML(String(itemVal))}</span>
                </div>
              `;
            })
            .join("");

          strip.innerHTML = `
            <div class="flow-mini-label">${this.escapeHTML(v.name)} (List Index View ${currentIdx !== null && v.rawValue[currentIdx] !== undefined ? `— ${v.name}[${currentIdx}] = ${v.rawValue[currentIdx]}` : ""})</div>
            <div class="list-cells-row">${cellsHTML}</div>
          `;
          this.visualListsContainer.appendChild(strip);
        }
      });
    }

    if (this.selectedHistoryVar) {
      this.renderVariableHistory(this.selectedHistoryVar, step);
    }
  }

  renderVariableHistory(varName, step) {
    const html = this.explainer.explainVariableClick(varName, step, this.traceResult);
    this.varHistoryBox.innerHTML = this.formatMarkdown(html);
    this.varHistoryBox.classList.remove("hidden");
  }

  renderBuiltInQuestionAnswer() {
    if (!this.traceResult || !this.traceResult.steps.length) return;
    const step = this.traceResult.steps[this.currentStepIdx];
    const ans = this.explainer.answerBuiltInQuestion(
      this.activeQuestionId,
      step,
      this.traceResult
    );
    this.questionAnswerBox.innerHTML = this.formatMarkdown(ans);
  }

  /* ==========================================
     PANEL D: 7-Part Beginner Explanation
     ========================================== */
  renderPanelDExplanation(step) {
    const exp = step.explanations;
    const whatLine =
      this.explanationMode === "technical" ? exp.whatTechnical : exp.whatBeginner;

    this.exp1WhatLineDoes.innerHTML = this.formatMarkdown(whatLine);
    this.exp2Symbols.innerHTML = this.formatMarkdown(exp.symbolsMeaning);
    this.exp3WhyNow.innerHTML = this.formatMarkdown(exp.whyExecuting);
    this.exp4VarsBefore.innerHTML = this.formatMarkdown(exp.variablesBefore);
    this.exp5ChangesAfter.innerHTML = this.formatMarkdown(exp.whatChangesAfter);
    this.exp6WhyCondition.innerHTML = this.formatMarkdown(exp.whyCondition);
    this.exp7NextLine.innerHTML = this.formatMarkdown(exp.whatNext);
  }

  formatMarkdown(str) {
    if (!str) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/&lt;br&gt;/g, "<br>")
      .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
      .replace(/`([^`]+)`/g, "<code>$1</code>");
  }

  escapeHTML(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }
}

