1346:   findSingleAssignmentEquals(str) {
1347:     let depth = 0;
1348:     let inSingle = false;
1349:     let inDouble = false;
1350:     for (let i = 0; i < str.length; i++) {
1351:       const ch = str[i];
1352:       if (ch === "'" && !inDouble) inSingle = !inSingle;
1353:       else if (ch === '"' && !inSingle) inDouble = !inDouble;
1354:       else if (!inSingle && !inDouble) {
1355:         if (ch === "(" || ch === "[" || ch === "{") depth++;
1356:         else if (ch === ")" || ch === "]" || ch === "}") depth--;
1357:         else if (
1358:           ch === "=" &&
1359:           depth === 0 &&
1360:           str[i - 1] !== "=" &&
1361:           str[i - 1] !== "!" &&
1362:           str[i - 1] !== "<" &&
1363:           str[i - 1] !== ">" &&
1364:           str[i + 1] !== "="
1365:         ) {
1366:           return i;
1367:         }
1368:       }
1369:     }
1370:     return -1;
1371:   }
