1373:   invokeFunctionNode(
1374:     fnNode,
1375:     argVals,
1376:     rawArgs,
1377:     callStack,
1378:     functions,
1379:     classes,
1380:     steps,
1381:     stdout,
1382:     loopStack,
1383:     callerLine
1384:   ) {
1385:     const newVars = {};
1386:     const paramBindings = [];
1387:     fnNode.params.forEach((p, idx) => {
1388:       const val = argVals[idx];
1389:       newVars[p] = Array.isArray(val) ? [...val] : val;
1390:       paramBindings.push({
1391:         param: p,
1392:         argExpr: rawArgs[idx] || p,
1393:         val: this.formatVal(val)
1394:       });
1395:     });
1396: 
1397:     const newFrame = {
1398:       frameName: `${fnNode.funcName}(${fnNode.params.map((p, i) => `${p}=${this.formatVal(argVals[i])}`).join(", ")})`,
1399:       vars: newVars,
1400:       prevVars: {}
1401:     };
1402: 
1403:     callStack.push(newFrame);
1404: 
1405:     const createdRows = fnNode.params.map((p) => ({
1406:       name: p,
1407:       previous: "—",
1408:       current: this.formatVal(newVars[p]),
1409:       rawValue: newVars[p],
1410:       type: this.getPythonType(newVars[p]),
1411:       status: "created"
1412:     }));
1413: 
1414:     steps.push({
1415:       stepIndex: steps.length + 1,
1416:       line: fnNode.line,
1417:       codeText: fnNode.text,
1418:       eventType: "FUNC_CALL",
1419:       functionName: newFrame.frameName,
1420:       beforeVars: {},
1421:       variables: createdRows,
1422:       changedVars: createdRows,
1423:       changedSummary: paramBindings.map((b) => `${b.param}: (arg) → ${b.val}`).join(", "),
1424:       condition: null,
1425:       loop: null,
1426:       operationDetail: {
1427:         kind: "func_call",
1428:         funcName: fnNode.funcName,
1429:         callerLine,
1430:         paramBindings
1431:       },
1432:       returnValue: null,
1433:       stdout: [...stdout]
1434:     });
