1449:   evaluateCondition(condExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line) {
1450:     const ops = ["==", "!=", ">=", "<=", ">", "<"];
1451:     for (const op of ops) {
1452:       const idx = condExpr.indexOf(op);
1453:       if (idx !== -1) {
1454:         const leftExpr = condExpr.slice(0, idx).trim();
1455:         const rightExpr = condExpr.slice(idx + op.length).trim();
1456:         const leftVal = this.evalExpr(leftExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line);
1457:         const rightVal = this.evalExpr(rightExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line);
1458:         const boolVal = Boolean(this.evalExpr(condExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line));
1459:         return {
1460:           expr: condExpr,
1461:           leftExpr,
1462:           leftVal: this.formatVal(leftVal),
1463:           operator: op,
1464:           rightExpr,
1465:           rightVal: this.formatVal(rightVal),
1466:           result: boolVal
1467:         };
1468:       }
1469:     }
1470:     const boolVal = Boolean(this.evalExpr(condExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line));
1471:     return {
1472:       expr: condExpr,
1473:       leftExpr: condExpr,
1474:       leftVal: this.formatVal(boolVal),
1475:       operator: "is",
1476:       rightExpr: "True",
1477:       rightVal: "True",
1478:       result: boolVal
1479:     };
1480:   }
