}

.thonny-expr-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
}

.thonny-badge {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #b45309;
}

.thonny-subcounter {
  font-family: var(--font-mono);
  font-weight: 600;
  color: #92400e;
  background: #fef3c7;
  padding: 2px 8px;
  border-radius: 99px;
}

.thonny-live-code {
  font-family: var(--font-mono);
  font-size: 15px;
  font-weight: 700;
  background: #ffffff;
  border: 1.5px solid #f59e0b;
  border-radius: 6px;
  padding: 8px 12px;
  color: var(--text-main);
}

.thonny-focus-note {
  font-size: 13.5px;
  color: #78350f;
  font-weight: 500;
}

.thonny-trail-chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
