args.ReplacementContent:
.editor-template-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 8px;
}

.chip-template {
  font-size: 11.5px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid #bfdbfe;
  background: #eff6ff;
  color: #1d4ed8;
  cursor: pointer;
  transition: all 0.12s ease;
}

.chip-template:hover {
  background: #dbeafe;
  border-color: #93c5fd;
}

/* =========================================================
   QUICK ITERATION / PHASE JUMP STRIP (INSIDE TEACHING CARD)
   ========================================================= */
.iteration-jump-strip {
  background: #f8fafc;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.iteration-jump-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.iteration-jump-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--text-secondary);
}

.iteration-active-badge {
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 700;
  color: var(--primary-blue);
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  padding: 2px 9px;
  border-radius: 999px;
}

.iteration-pills-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.iter-pill-btn {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  padding: 5px 11px;
  border-radius: 7px;
  border: 1px solid var(--border-medium);
  background: #ffffff;
  color: var(--text-secondary);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.12s ease;
}

.iter-pill-btn:hover {
  border-color: var(--primary-blue);
  color: var(--primary-blue);
  background: #eff6ff;
}

.iter-pill-btn.is-active-iter-pill {
  background: var(--primary-blue);
  border-color: var(--primary-blue);
  color: #ffffff;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.22);
}

.iter-pill-btn.is-past-iter-pill {
  background: #f1f5f9;
  color: #334155;
  border-color: #cbd5e1;
}

/* =========================================================
   AREA 4: COMPLETE CODE ITERATION & ALL-STEPS DRY-RUN EXPLORER
   ========================================================= */
.iterations-explorer-section {
  margin: 0 28px 28px 28px;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 22px 24px;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.iterations-explorer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-light);
}

.iterations-title-group {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.iterations-main-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-main);
}

.iterations-summary-badge {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
}

.iterations-controls-group {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.view-mode-tabs {
  display: inline-flex;
  background: #f1f5f9;
  padding: 3px;
  border-radius: 9px;
  border: 1px solid var(--border-light);
}

.view-tab-btn {
  font-family: var(--font-sans);
  font-size: 12.5px;
  font-weight: 600;
  padding: 6px 13px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.12s ease;
}

.view-tab-btn.active {
  background: #ffffff;
  color: var(--primary-blue);
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.08);
}

.iterations-helper-note {
  font-size: 13.5px;
  color: var(--text-secondary);
}

/* Grouped Iteration Cards Grid */
.iterations-grouped-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.iter-group-card {
  border: 1px solid var(--border-medium);
  border-radius: var(--radius-md);
  background: #ffffff;
  overflow: hidden;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.iter-group-card.is-active-group {
  border: 2px solid var(--primary-blue);
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.1);
}

.iter-group-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  padding: 11px 16px;
  background: #f8fafc;
  border-bottom: 1px solid var(--border-light);
  cursor: pointer;
  user-select: none;
}

.iter-group-card.is-active-group .iter-group-header {
  background: #eff6ff;
  border-bottom-color: #bfdbfe;
}

.iter-group-left {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.iter-group-badge {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 6px;
  background: #e2e8f0;
  color: #1e293b;
}

.iter-group-card.is-active-group .iter-group-badge {
  background: var(--primary-blue);
  color: #ffffff;
}

.iter-group-title {
  font-size: 14.5px;
  font-weight: 700;
  color: var(--text-main);
}

.iter-group-right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.iter-group-state-pill {
  font-family: var(--font-mono);
  font-size: 12px;
  color: #065f46;
  background: #ecfdf5;
  border: 1px solid #a7f3d0;
  padding: 3px 10px;
  border-radius: 6px;
  max-width: 440px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.iter-group-step-range {
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-muted);
}

.iter-group-steps-list {
  display: flex;
  flex-direction: column;
}

.iter-step-row {
  display: grid;
  grid-template-columns: 76px 64px minmax(210px, 1.1fr) minmax(260px, 1.8fr) minmax(180px, 1.1fr);
  align-items: center;
  gap: 12px;
  padding: 9px 16px;
  border-bottom: 1px solid #f1f5f9;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.1s ease;
}

.iter-step-row:last-child {
  border-bottom: none;
}

.iter-step-row:hover {
  background: #f8fafc;
}

.iter-step-row.is-current-step-row {
  background: #dbeafe;
  font-weight: 600;
}

.iter-step-num {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  color: var(--primary-blue);
}

.iter-step-line {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text-muted);
}

.iter-step-code {
  font-family: var(--font-mono);
  font-size: 12.5px;
  background: #f8fafc;
  padding: 3px 8px;
  border-radius: 5px;
  border: 1px solid var(--border-light);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.iter-step-meaning {
  color: var(--text-main);
  font-size: 13px;
  line-height: 1.4;
}

.iter-step-delta {
  font-family: var(--font-mono);
  font-size: 12px;
  color: #065f46;
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Full Dry-Run Table (All Steps 1 -> N) */
.dryrun-table-scroll {
  max-height: 540px;
  overflow-y: auto;
  border: 1px solid var(--border-medium);
  border-radius: var(--radius-md);
}

.dryrun-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.dryrun-table thead th {
  position: sticky;
  top: 0;
  background: #f1f5f9;
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-medium);
  z-index: 2;
}

.dryrun-table tbody tr {
  border-bottom: 1px solid var(--border-light);
  cursor: pointer;
  transition: background 0.1s ease;
}

.dryrun-table tbody tr:hover {
  background: #f8fafc;
}

.dryrun-table tbody tr.is-active-dryrun-row {
  background: #dbeafe;
}

.dryrun-table td {
  padding: 9px 12px;
  vertical-align: middle;
}

.dryrun-mono {
  font-family: var(--font-mono);
  font-size: 12px;
}

.hidden {
  display: none !important;
}

@media (max-width: 1180px) {
  .three-area-workspace {
    grid-template-columns: 1fr;
  }
  .advanced-grid {
    grid-template-columns: 1fr 1fr;
  }
  .iter-step-row {
    grid-template-columns: 70px 60px 1fr;
  }
}

