/* =========================================================
   PHASE 2 & PHASE 3: VISUAL VARIABLE BOXES, ANIMATIONS,
   CONDITIONS & LOOP TRACKERS
   ========================================================= */

/* 1. Labeled Variable Box Cards */
.var-boxes-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: stretch;
}

.var-box-card {
  flex: 1 1 120px;
  max-width: 170px;
  border: 2px solid var(--border-medium);
  border-radius: var(--radius-md);
  background: #ffffff;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.05);
  transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
  position: relative;
}

.var-box-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(15, 23, 42, 0.08);
}

.var-box-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.var-box-label strong {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--primary-blue);
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  padding: 1px 6px;
  border-radius: 4px;
}

.var-box-val-slot {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  border-radius: 6px;
  padding: 6px 9px;
  min-height: 38px;
}

.var-box-value {
  font-family: var(--font-mono);
  font-size: 18px;
  font-weight: 800;
  color: var(--text-main);
  animation: popIn 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.var-box-prev {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
}

.var-box-card.is-updated {
  border-color: #10b981;
  background: #ecfdf5;
  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.18);
  animation: highlightPulse 0.6s ease;
}

.var-box-card.is-negative-warning {
  border-color: #f43f5e;
  background: #fff1f2;
}

.var-box-card.is-negative-warning .var-box-value {
  color: #be123c;
}

/* 2. Number Moving Into Variable Stage (Phase 2) */
.visual-calc-stage {
  background: #f8fafc;
  border: 1.5px solid #cbd5e1;
  border-radius: var(--radius-md);
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.calc-stage-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--text-secondary);
}

.calc-stage-badge {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
}

.assign-animation-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 8px 12px;
  background: #ffffff;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
}

.anim-source-val {
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 800;
  color: #1e40af;
  background: #dbeafe;
  border: 1.5px solid #93c5fd;
  padding: 5px 12px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  animation: slideRightToBox 0.45s ease;
}

.anim-move-arrow {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 700;
  color: #2563eb;
  letter-spacing: 0.3px;
  animation: arrowPulse 0.9s infinite alternate;
}

.calc-equation-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 14.5px;
}

.calc-operand-chip {
  padding: 5px 11px;
  border-radius: 6px;
  background: #ffffff;
  border: 1.5px solid var(--border-medium);
  font-weight: 700;
  color: var(--text-main);
}

.calc-operator-chip {
  font-weight: 900;
  font-size: 16px;
  color: #2563eb;
  padding: 0 4px;
}

.calc-result-chip {
  padding: 5px 13px;
  border-radius: 6px;
  background: var(--changed-green-bg);
  border: 2px solid var(--changed-green-border);
  color: var(--changed-green-text);
  font-weight: 800;
  animation: popIn 0.4s ease;
}

/* 3. Negative Value Reset Visual Warning (Phase 2) */
.negative-reset-visual {
  background: #fff1f2;
  border: 2px dashed #fca5a5;
  border-radius: var(--radius-md);
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.neg-warning-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13.5px;
  font-weight: 800;
  color: #991b1b;
}

.neg-warning-icon {
  font-size: 18px;
  animation: shake 0.6s ease;
}

.neg-reset-flow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  font-family: var(--font-mono);
  font-size: 14px;
}

.neg-discarded-val {
  color: #991b1b;
  background: #fee2e2;
  border: 1px solid #fca5a5;
  padding: 4px 10px;
  border-radius: 6px;
  text-decoration: line-through;
  opacity: 0.75;
  font-weight: 700;
}

.neg-discard-arrow {
  color: #b91c1c;
  font-weight: 800;
  font-size: 13px;
}

.zero-reset-box {
  background: #ecfdf5;
  border: 2px solid #10b981;
  color: #047857;
  padding: 4px 12px;
  border-radius: 6px;
  font-weight: 800;
  font-size: 15px;
  animation: popIn 0.45s ease;
}

/* 4. Condition Gate & Decision Visualizer (Phase 3) */
.visual-condition-gate {
  background: #f0f9ff;
  border: 1.5px solid #bae6fd;
  border-radius: var(--radius-md);
  padding: 13px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.cond-gate-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #0369a1;
}

.cond-balance-row {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  padding: 10px 14px;
  background: #ffffff;
  border: 1px solid #e0f2fe;
  border-radius: var(--radius-sm);
}

.cond-val-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  font-family: var(--font-mono);
  background: #f8fafc;
  border: 1.5px solid var(--border-medium);
  padding: 6px 14px;
  border-radius: 6px;
}

.cond-val-name {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 600;
}

.cond-val-num {
  font-size: 17px;
  font-weight: 800;
  color: var(--text-main);
}

.cond-op-badge {
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 900;
  color: #0284c7;
  background: #e0f2fe;
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid #7dd3fc;
}

.decision-badge {
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 800;
  padding: 5px 14px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  letter-spacing: 0.4px;
  animation: popIn 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.decision-badge.is-true {
  background: #ecfdf5;
  border: 2px solid #10b981;
  color: #065f46;
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.25);
}

.decision-badge.is-false {
  background: #fff1f2;
  border: 2px solid #f43f5e;
  color: #9f1239;
  box-shadow: 0 2px 8px rgba(244, 63, 94, 0.25);
}

.branch-decision-wrap {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.branch-option {
  border: 1.5px solid var(--border-light);
  border-radius: 8px;
  padding: 9px 12px;
  background: #ffffff;
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition: all 0.2s ease;
}

.branch-option-tag {
  font-size: 10.5px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  padding: 2px 7px;
  border-radius: 999px;
  align-self: flex-start;
}

.branch-option code {
  font-family: var(--font-mono);
  font-size: 13.5px;
  font-weight: 700;
}

.branch-option.is-active-branch {
  border: 2px solid #10b981;
  background: #f0fdf4;
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.15);
}

.branch-option.is-active-branch .branch-option-tag {
  background: #10b981;
  color: #ffffff;
}

.branch-option.is-active-branch code {
  color: #065f46;
}

.branch-option.is-skipped-branch {
  border: 1.5px dashed #cbd5e1;
  background: #f8fafc;
  opacity: 0.6;
}

.branch-option.is-skipped-branch .branch-option-tag {
  background: #e2e8f0;
  color: #64748b;
}

.branch-option.is-skipped-branch code {
  color: #64748b;
}

/* 5. Loop Pointer & List Element Tracker (Phase 3) */
.visual-loop-strip {
  background: #f8fafc;
  border: 1.5px solid #cbd5e1;
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.loop-strip-header {
  display: flex;
