  // Keyboard shortcuts: Left / Right arrows + F7 for Thonny sub-expression stepping, 1-4 for Quiz options
  window.addEventListener("keydown", (e) => {
    if (document.activeElement === this.codeTextarea) {
      return;
    }
    if (this.quizModeEnabled && ["1", "2", "3", "4"].includes(e.key)) {
      const step = this.traceResult && this.traceResult.steps ? this.traceResult.steps[this.currentStepIdx] : null;
      if (step && step.quizQuestion) {
        const answerState = this.quizAnswers.get(step.stepIndex);
        if (!answerState || !answerState.answered) {
          const optIdx = Number(e.key) - 1;
          const opt = step.quizQuestion.options[optIdx];
          if (opt) {
            e.preventDefault();
            const isCorrect = Boolean(opt.isCorrect);
            this.quizScore.total++;
            if (isCorrect) this.quizScore.correct++;
            this.quizAnswers.set(step.stepIndex, {
              selectedIdx: optIdx,
              isCorrect,
              answered: true,
              skipped: false
            });
            this.renderStep();
            return;
          }
        }
      }
    }
    if (e.key === "ArrowRight") {
      e.preventDefault();
      this.stopAutoPlay();
      this.goToNextSubstep();
    } else if (e.key === "ArrowLeft") {
      e.preventDefault();
      this.stopAutoPlay();
      this.goToPrevSubstep();
    } else if (e.key === "F7") {
      e.preventDefault();
      this.stopAutoPlay();
      this.goToNextSubstep();
    }
  });
}

