// Test script for Phase 1 verification
const fs = require('fs');

// Create mock window environment
global.window = {};
require('./app_build/engine.js');
require('./app_build/explainer.js');

const engine = new window.PythonExecutionEngine();
const explainer = new window.RuleBasedExplainer();

const defaultProg = window.PRELOADED_PROGRAMS['max_subarray'];
console.log('Testing program:', defaultProg.title);

const rawTrace = engine.trace(defaultProg.code, defaultProg.defaultInput);
console.log('Engine trace ok:', rawTrace.ok, 'steps:', rawTrace.steps.length);
if (!rawTrace.ok) {
  console.error('Trace error:', rawTrace.errorMessage);
  process.exit(1);
}

const enrichedTrace = explainer.enrichTraceWithExplanations(rawTrace);
console.log('Best subarray max sum:', enrichedTrace.bestSubarrayInfo.maxSum);
if (enrichedTrace.bestSubarrayInfo.maxSum !== 6) {
  console.error('FAIL: Expected max sum 6, got', enrichedTrace.bestSubarrayInfo.maxSum);
  process.exit(1);
}

// Verify that NO step has unescaped raw HTML like <span style="..."
let foundRawHTML = false;
enrichedTrace.steps.forEach((step, sIdx) => {
  const substeps = step.teachingSubsteps || [step.teacherLesson];
  substeps.forEach((sub, subIdx) => {
    const text = (sub.whatIsHappening || '') + ' ' + (sub.whatItMeans || '');
    if (/<span\s+style=|<div\s+class=/i.test(text)) {
      console.error(`Step ${sIdx + 1} substep ${subIdx + 1} has raw HTML markup in text:`, text);
      foundRawHTML = true;
    }
  });
});

if (foundRawHTML) {
  console.error('FAIL: Raw HTML found in explanations');
  process.exit(1);
}

console.log('All explanations clean: ZERO raw HTML found!');
console.log('Total steps:', enrichedTrace.steps.length);
console.log('SUCCESS: Phase 1 verification passed!');

// Test script for Phase 1 verification across all test cases
global.window = {};
require('./app_build/engine.js');
require('./app_build/explainer.js');

const engine = new window.PythonExecutionEngine();
const explainer = new window.RuleBasedExplainer();
const code = window.PRELOADED_PROGRAMS['max_subarray'].code;

const testCases = [
  { input: "nums = [-2, 1, -3, 4, -1, 2, 1, -5, 4]", expectedMax: 6, label: "Mixed" },
  { input: "nums = [-5, -2, -8, -1, -4]", expectedMax: -1, label: "All-Negative" },
  { input: "nums = [1, 2, 3, 4, 5]", expectedMax: 15, label: "All-Positive" },
  { input: "nums = [-7]", expectedMax: -7, label: "Single Negative" },
  { input: "nums = [42]", expectedMax: 42, label: "Single Positive" }
];

testCases.forEach((tc) => {
  const raw = engine.trace(code, tc.input);
  if (!raw.ok) {
    console.error(`Trace failed for ${tc.label}:`, raw.errorMessage);
    process.exit(1);
  }
  const enriched = explainer.enrichTraceWithExplanations(raw);
  const actualMax = enriched.bestSubarrayInfo.maxSum;
  console.log(`[PASS] ${tc.label}: expected ${tc.expectedMax}, got ${actualMax} (${enriched.steps.length} steps)`);
  if (actualMax !== tc.expectedMax) {
    console.error(`FAIL for ${tc.label}`);
    process.exit(1);
  }
});

console.log('ALL 5 TEST CASES VERIFIED PERFECTLY!');

