const fs = require("fs");
const engineCode = fs.readFileSync("app_build/engine.js", "utf8");
const explainerCode = fs.readFileSync("app_build/explainer.js", "utf8");

// Mock window / browser globals
global.window = global;
eval(engineCode);
eval(explainerCode);

const engine = new window.PythonFlowEngine();
const explainer = new window.TeacherExplainer();

console.log("Testing Engine & Explainer loaded successfully.");

// 1. Kadane Maximum Subarray
const kadaneCode = `class Solution:
    def maxSubArray(self, nums):
        c = 0
        ans = nums[0]
        for i in range(len(nums)):
            c += nums[i]
            if c >= ans:
                ans = c
            if c < 0:
                c = 0
        return ans`;

const testInputs = [
  { name: "Mixed (Original)", input: "nums = [-2, 1, -3, 4, -1, 2, 1, -5, 4]", expected: "6" },
  { name: "All-Negative", input: "nums = [-5, -2, -8, -1, -4]", expected: "-1" },
  { name: "All-Positive", input: "nums = [1, 2, 3, 4, 5]", expected: "15" },
  { name: "Single Negative", input: "nums = [-7]", expected: "-7" },
  { name: "Single Positive", input: "nums = [42]", expected: "42" }
];

let allPassed = true;

for (const t of testInputs) {
  const fullCode = `${kadaneCode}\n${t.input}\nprint(Solution().maxSubArray(nums))`;
  const trace = engine.execute(fullCode);
  const steps = explainer.enrichTraceWithTeachingSteps(trace);

  const returnStep = steps.find(s => s.eventType === "RETURN");
  const actual = returnStep ? String(returnStep.returnValue) : null;
  const passed = actual === t.expected;
  if (!passed) allPassed = false;
  console.log(`[${passed ? "PASS" : "FAIL"}] ${t.name}: expected ${t.expected}, got ${actual}, total steps: ${steps.length}`);

  // Verify all substeps have label, whatIsHappening, whyNecessary, whatHappensNext
  for (const s of steps) {
    if (!s.teachingSubsteps || s.teachingSubsteps.length === 0) {
      console.error(`Step ${s.stepIndex} has no teaching substeps!`);
      allPassed = false;
    }
    for (const sub of s.teachingSubsteps) {
      if (!sub.substepLabel || !sub.whatIsHappening || !sub.whyNecessary || !sub.whatHappensNext) {
        console.error(`Substep missing required teaching fields in step ${s.stepIndex}:`, sub);
        allPassed = false;
      }
    }
  }
}

// 2. Binary search with while loop
const bsCode = `def binary_search(nums, target):
    left = 0
    right = len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
nums = [10, 20, 30, 40, 50, 60]
print(binary_search(nums, 40))`;

const bsTrace = engine.execute(bsCode);
const bsSteps = explainer.enrichTraceWithTeachingSteps(bsTrace);
const bsReturn = bsSteps.find(s => s.eventType === "RETURN");
const bsPassed = bsReturn && String(bsReturn.returnValue) === "3";
console.log(`[${bsPassed ? "PASS" : "FAIL"}] Binary Search: expected 3, got ${bsReturn ? bsReturn.returnValue : null}`);

// Check while loop substeps
const whileIter = bsSteps.find(s => s.operationDetail && s.operationDetail.kind === "while_check" && s.eventType === "LOOP_ITER");
console.log("While Loop Iter substep 1 label:", whileIter ? whileIter.teachingSubsteps[0].substepLabel : "NONE");
console.log("While Loop Iter substep 2 label:", whileIter ? whileIter.teachingSubsteps[1].substepLabel : "NONE");

// Check mid calculation substeps
const midAssign = bsSteps.find(s => s.operationDetail && s.operationDetail.target === "mid");
console.log("Mid calculation substep 1 label:", midAssign ? midAssign.teachingSubsteps[0].substepLabel : "NONE");
console.log("Mid calculation substep 2 label:", midAssign ? midAssign.teachingSubsteps[1].substepLabel : "NONE");
console.log("Mid calculation substep 3 label:", midAssign ? midAssign.teachingSubsteps[2].substepLabel : "NONE");

// 3. Stack Class with list mutation
const stackCode = `class Stack:
    def __init__(self):
        self.items = []
    def push(self, item):
        self.items.append(item)
    def pop(self):
        return self.items.pop()
s = Stack()
s.push(10)
s.push(20)
print(s.pop())`;

const stackTrace = engine.execute(stackCode);
const stackSteps = explainer.enrichTraceWithTeachingSteps(stackTrace);
const stackPrint = stackSteps.find(s => s.eventType === "PRINT");
const stackPassed = stackPrint && stackTrace.stdout.includes("20");
console.log(`[${stackPassed ? "PASS" : "FAIL"}] Stack Class: expected stdout 20, got ${stackTrace.stdout}`);

// Check class def substeps
const classStep = stackSteps.find(s => s.eventType === "CLASS_DEF");
console.log("Class def substep label:", classStep ? classStep.teachingSubsteps[0].substepLabel : "NONE");
console.log("Class def whatIsHappening:", classStep ? classStep.teachingSubsteps[0].whatIsHappening : "NONE");

if (allPassed && bsPassed && stackPassed) {
  console.log("ALL TESTS PASSED SUCCESSFULLY! 100% VERIFIED.");
} else {
  console.error("SOME TESTS FAILED.");
  process.exit(1);
}
