.var-box-card {
  flex: 1 1 120px;
  max-width: 170px;
  border: 2px solid var(--border-medium);
  border-radius: var(--radius-md);
  background: #ffffff;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.05);
  transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
  position: relative;
  animation: varCardPop calc(0.35s * var(--anim-speed-factor, 1)) ease-out;
}

.var-box-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(15, 23, 42, 0.08);
}

.var-box-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  flex-wrap: wrap;
}

.var-box-label strong {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--primary-blue);
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  padding: 1px 6px;
  border-radius: 4px;
}

.var-status-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.var-status-badge.is-created {
  background: #dbeafe;
  color: #1d4ed8;
  border: 1px solid #93c5fd;
  animation: popIn calc(0.3s * var(--anim-speed-factor, 1)) ease;
}

.var-status-badge.is-updated {
  background: #d1fae5;
  color: #047857;
  border: 1px solid #6ee7b7;
  animation: popIn calc(0.3s * var(--anim-speed-factor, 1)) ease;
}

.var-status-badge.is-negative {
  background: #fee2e2;
  color: #b91c1c;
  border: 1px solid #fca5a5;
  animation: shake calc(0.5s * var(--anim-speed-factor, 1)) ease;
}

.var-box-val-slot {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  border-radius: 6px;
  padding: 6px 9px;
  min-height: 38px;
}

.var-box-value {
  font-family: var(--font-mono);
  font-size: 18px;
  font-weight: 800;
  color: var(--text-main);
  animation: numPopIn calc(0.35s * var(--anim-speed-factor, 1)) cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.var-box-prev {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
}

.var-box-card.is-created {
  border-color: #3b82f6;
  background: #eff6ff;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
  animation: varCreatedGlow calc(0.6s * var(--anim-speed-factor, 1)) ease;
}

.var-box-card.is-updated {
  border-color: #10b981;
  background: #ecfdf5;
  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.2);
  animation: varUpdatedGlow calc(0.6s * var(--anim-speed-factor, 1)) ease;
}

.var-box-card.is-negative-warning {
  border-color: #f43f5e;
  background: #fff1f2;
  box-shadow: 0 0 0 3px rgba(244, 63, 94, 0.2);
}

.var-box-card.is-negative-warning .var-box-value {
  color: #be123c;
}

