.top-bar {
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border-light);
  padding: 8px 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: sticky;
  top: 0;
  z-index: 20;
}

.top-bar-primary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
}

.brand-area {
  display: flex;
  align-items: center;
  gap: 10px;
}

.teacher-badge {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.step-progress-label {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--primary-blue);
  background: var(--primary-blue-soft);
  border: 1px solid var(--primary-blue-border);
  padding: 3px 10px;
  border-radius: 99px;
}

/* Scope Pills (Global vs. Local) */
.scope-pill {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 99px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.scope-global {
  background: var(--global-teal-soft);
  color: var(--global-teal);
  border: 1px solid var(--global-teal-border);
}

.scope-local {
  background: var(--local-purple-soft);
  color: var(--local-purple);
  border: 1px solid var(--local-purple-border);
}

.top-bar-secondary {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  width: 100%;
  padding-top: 6px;
  border-top: 1px solid var(--border-light);
}

.nav-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-nav {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 600;
  padding: 6px 13px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-medium);
  background: var(--bg-card);
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-nav:hover:not(:disabled) {
  background: var(--bg-subtle);
  border-color: #94a3b8;
}

.btn-nav:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn-substep {
  background: #fffbeb;
  border-color: #fcd34d;
  color: #92400e;
}

.btn-substep:hover:not(:disabled) {
  background: #fef3c7;
  border-color: #f59e0b;
}

.btn-next-prominent {
  background: var(--primary-blue);
  border-color: var(--primary-blue);
  color: #ffffff;
  padding: 7px 18px;
  font-size: 13.5px;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25);
}

.btn-next-prominent:hover:not(:disabled) {
  background: var(--primary-blue-hover);
  border-color: var(--primary-blue-hover);
}

.secondary-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.btn-subtle {
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 500;
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-light);
  background: var(--bg-subtle);
  color: var(--text-secondary);
  cursor: pointer;
}

.btn-subtle:hover,
.btn-subtle.active {
  background: #e2e8f0;
  color: var(--text-main);
}

.btn-small-primary {
  font-family: var(--font-sans);
