args.ReplacementContent:
.var-boxes-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: stretch;
}

.var-box-card {
  flex: 1 1 80px;
  max-width: 130px;
  border: 2px solid var(--border-medium);
  border-radius: var(--radius-md);
  background: #ffffff;
  padding: 4px 8px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.05);
  transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
  position: relative;
  animation: varCardPop calc(0.35s * var(--anim-speed-factor, 1)) ease-out;
}

.var-box-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(15, 23, 42, 0.08);
}

.var-box-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  flex-wrap: wrap;
}

.var-box-label strong {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--primary-blue);
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  padding: 0 4px;
  border-radius: 4px;
}

.var-status-badge {
  font-size: 9.5px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.2px;
}

.var-status-badge.is-created {
  background: #dbeafe;
  color: #1d4ed8;
  border: 1px solid #93c5fd;
  animation: popIn calc(0.3s * var(--anim-speed-factor, 1)) ease;
}

.var-status-badge.is-updated {
  background: #d1fae5;
  color: #047857;
  border: 1px solid #6ee7b7;
  animation: popIn calc(0.3s * var(--anim-speed-factor, 1)) ease;
}

.var-status-badge.is-negative {
  background: #fee2e2;
  color: #b91c1c;
  border: 1px solid #fca5a5;
  animation: shake calc(0.5s * var(--anim-speed-factor, 1)) ease;
}

.var-box-val-slot {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 4px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  border-radius: 5px;
  padding: 2px 6px;
  min-height: 26px;
}

.var-box-value {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 800;
  color: var(--text-main);
  animation: numPopIn calc(0.35s * var(--anim-speed-factor, 1)) cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.var-box-prev {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-muted);
  white-space: nowrap;
}

.var-box-card.is-created {
  border-color: #3b82f6;
  background: #eff6ff;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
  animation: varCreatedGlow calc(0.6s * var(--anim-speed-factor, 1)) ease;
}

.var-box-card.is-updated {
  border-color: #10b981;
  background: #ecfdf5;
  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.2);
  animation: varUpdatedGlow calc(0.6s * var(--anim-speed-factor, 1)) ease;
}

.var-box-card.is-negative-warning {
  border-color: #f43f5e;
  background: #fff1f2;
  box-shadow: 0 0 0 3px rgba(244, 63, 94, 0.2);
}

.var-box-card.is-negative-warning .var-box-value {
  color: #be123c;
}

/* 2. Number Moving Into Variable Stage (Phase 2) */
.visual-calc-stage {
  background: #f8fafc;
  border: 1.5px solid #cbd5e1;
  border-radius: var(--radius-md);
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.calc-stage-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--text-secondary);
}

.calc-stage-badge {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
}

.assign-animation-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 5px 9px;
  background: #ffffff;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
}

.anim-source-val {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 800;
  color: #1e40af;
  background: #dbeafe;
  border: 1.5px solid #93c5fd;
  padding: 3px 8px;
  border-radius: 5px;
  display: inline-flex;
  align-items: center;
  animation: numberGlide calc(0.45s * var(--anim-speed-factor, 1)) cubic-bezier(0.16, 1, 0.3, 1);
}

.anim-move-arrow {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 700;
  color: #2563eb;
  letter-spacing: 0.3px;
  animation: arrowGlide calc(0.8s * var(--anim-speed-factor, 1)) infinite alternate ease-in-out;
}

.calc-equation-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 13px;
}

.calc-operand-chip {
  padding: 3px 8px;
  border-radius: 5px;
  background: #ffffff;
  border: 1.5px solid var(--border-medium);
  font-weight: 700;
  color: var(--text-main);
  animation: operandAppear calc(0.3s * var(--anim-speed-factor, 1)) ease-out;
}

.calc-operator-chip {
  font-weight: 900;
  font-size: 14px;
  color: #2563eb;
  padding: 0 3px;
}

.calc-result-chip {
  padding: 3px 9px;
  border-radius: 5px;
  background: var(--changed-green-bg);
  border: 2px solid var(--changed-green-border);
  color: var(--changed-green-text);
  font-weight: 800;
  animation: calcResultPop calc(0.4s * var(--anim-speed-factor, 1)) cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

/* 3. Negative Value Reset Visual Warning (Phase 2) */
.negative-reset-visual {
  background: #fff1f2;
  border: 1.5px dashed #fca5a5;
  border-radius: var(--radius-md);
  padding: 7px 11px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  animation: varCardPop calc(0.35s * var(--anim-speed-factor, 1)) ease-out;
}

.neg-warning-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 800;
  color: #991b1b;
}

.neg-warning-icon {
  font-size: 15px;
  animation: shake calc(0.6s * var(--anim-speed-factor, 1)) ease;
}

.neg-reset-flow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 12.5px;
}

.neg-discarded-val {
  color: #991b1b;
  background: #fee2e2;
  border: 1px solid #fca5a5;
  padding: 2px 7px;
  border-radius: 5px;
  text-decoration: line-through;
  opacity: 0.75;
  font-weight: 700;
  animation: discardNegative calc(0.5s * var(--anim-speed-factor, 1)) ease;
}

.neg-discard-arrow {
  color: #b91c1c;
  font-weight: 800;
  font-size: 12px;
  animation: arrowGlide calc(0.8s * var(--anim-speed-factor, 1)) infinite alternate ease-in-out;
}

.zero-reset-box {
  background: #ecfdf5;
  border: 1.5px solid #10b981;
  color: #047857;
  padding: 2px 8px;
  border-radius: 5px;
